INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points) VALUES
('059cf774-2cd3-5e78-99a1-6047b804fbfc', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '521788f0-c0f7-5ff9-94e2-bd6a8cd8daac', 'a-level', '27.1', '9702 coursebook 27.1 · Alternating current and r.m.s. values', 9, 9, 'A North American socket supplies 120 V r.m.s. What is the peak voltage?', NULL, 1, 'numeric'::answer_type, '169.7', 'V', false, NULL, false, NULL, 'V₀ = √2 × V_rms = √2 × 120 = 170 V. Mark scheme (2 marks). C1: V₀ = √2 V_rms. A1: V₀ = 170 V.', 2),
('bd5c1bc2-688b-5936-bbb2-eb2040dad36b', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '521788f0-c0f7-5ff9-94e2-bd6a8cd8daac', 'a-level', '27.1', '9702 coursebook 27.1 · Alternating current and r.m.s. values', 10, 10, 'Which relationship is correct for a sinusoidal alternating current?', NULL, 1, 'multiple_choice'::answer_type, 'I_rms = I₀/√2', NULL, false, NULL, false, NULL, 'For a sine wave the mean of I² is I₀²/2. Mark scheme (1 mark). B1: C (I_rms = I₀/√2).', 1),
('7877621f-7a19-5768-abd5-aa9676d08c77', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '521788f0-c0f7-5ff9-94e2-bd6a8cd8daac', 'a-level', '27.1', '9702 coursebook 27.1 · Alternating current and r.m.s. values', 11, 11, 'The current through a lamp varies sinusoidally with an amplitude of 2.4 A. Calculate the r.m.s. current.', NULL, 1, 'numeric'::answer_type, '1.697', 'A', false, NULL, false, NULL, 'I_rms = I₀/√2 = 2.4 ÷ √2 = 1.70 A. Mark scheme (2 marks). C1: I_rms = I₀/√2. A1: I_rms = 1.70 A.', 2),
('83dd3c91-0c46-57bf-a110-c1c208867820', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '521788f0-c0f7-5ff9-94e2-bd6a8cd8daac', 'a-level', '27.1', '9702 coursebook 27.1 · Alternating current and r.m.s. values', 12, 12, 'What is the mean value of a sinusoidal alternating current over one complete cycle?', NULL, 1, 'multiple_choice'::answer_type, 'Zero', NULL, false, NULL, false, NULL, 'The positive and negative halves cancel. Mark scheme (1 mark). B1: A (Zero).', 1),
('a4e411a0-549d-53e3-a7a9-eb5bd6fbb384', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '521788f0-c0f7-5ff9-94e2-bd6a8cd8daac', 'a-level', '27.1', '9702 coursebook 27.1 · Alternating current and r.m.s. values', 13, 13, 'One complete cycle of an alternating supply lasts 16.7 ms. Calculate its frequency.', NULL, 1, 'numeric'::answer_type, '59.88', 'Hz', false, NULL, false, NULL, 'f = 1/T = 1 ÷ 16.7 × 10⁻³ = 59.9 Hz. Mark scheme (2 marks). C1: f = 1/T. A1: f = 59.9 Hz.', 2),
('0c9d06cb-52a1-5edd-b12a-c08568897db8', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '521788f0-c0f7-5ff9-94e2-bd6a8cd8daac', 'a-level', '27.1', '9702 coursebook 27.1 · Alternating current and r.m.s. values', 14, 14, 'Why is the r.m.s. value used to describe an alternating current, rather than its mean value?', NULL, 1, 'multiple_choice'::answer_type, 'The mean is zero, but the heating effect depends on I², which is always positive', NULL, false, NULL, false, NULL, 'The r.m.s. value gives the same heating as an equal steady current. Mark scheme (1 mark). B1: D (The mean is zero, but the heating effect depends on I², which is always positive).', 1),
('5225cac5-221a-529f-9505-c410f044d045', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '521788f0-c0f7-5ff9-94e2-bd6a8cd8daac', 'a-level', '27.1', '9702 coursebook 27.1 · Alternating current and r.m.s. values', 15, 15, 'A 46 Ω resistor is connected to a 230 V r.m.s. supply. Calculate the peak current.', NULL, 1, 'numeric'::answer_type, '7.071', 'A', false, NULL, false, NULL, 'I_rms = 230 ÷ 46 = 5.0 A. I₀ = √2 × 5.0 = 7.07 A. Mark scheme (2 marks). C1: I_rms then × √2. A1: I₀ = 7.07 A.', 2),
('5c1e1d60-4772-5a61-b678-b681c1022c87', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '521788f0-c0f7-5ff9-94e2-bd6a8cd8daac', 'a-level', '27.1', '9702 coursebook 27.1 · Alternating current and r.m.s. values', 16, 16, 'For a sinusoidal supply, what is (peak value) ÷ (r.m.s. value)?', NULL, 1, 'multiple_choice'::answer_type, '√2', NULL, false, NULL, false, NULL, 'For a sine wave V₀ = √2 V_rms, so the ratio is √2 ≈ 1.41. Mark scheme (1 mark). B1: B (√2).', 1),
('67c07985-960f-5848-982b-68660f4fa4ce', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '521788f0-c0f7-5ff9-94e2-bd6a8cd8daac', 'a-level', '27.1', '9702 coursebook 27.1 · Alternating current and r.m.s. values', 17, 17, 'A 50 Ω heater gives the same power on a steady current of 4.0 A as on a sinusoidal alternating current. Calculate the peak value of the alternating current.', NULL, 1, 'numeric'::answer_type, '5.657', 'A', false, NULL, false, NULL, 'The r.m.s. current equals the equivalent steady current, 4.0 A, so I₀ = √2 × 4.0 = 5.66 A. Mark scheme (2 marks). C1: I_rms = equivalent d.c. A1: I₀ = 5.66 A.', 2),
('03aec400-4130-5fc4-a3e0-62fdfb8e0612', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '521788f0-c0f7-5ff9-94e2-bd6a8cd8daac', 'a-level', '27.1', '9702 coursebook 27.1 · Alternating current and r.m.s. values', 18, 18, 'What is the unit of frequency?', NULL, 1, 'multiple_choice'::answer_type, 'Hz, equivalent to s⁻¹', NULL, false, NULL, false, NULL, 'Frequency is the number of cycles per second. Mark scheme (1 mark). B1: C (Hz, equivalent to s⁻¹).', 1),
('5cd20b14-9ea3-5883-811c-58e236e7a61a', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '521788f0-c0f7-5ff9-94e2-bd6a8cd8daac', 'a-level', '27.1', '9702 coursebook 27.1 · Alternating current and r.m.s. values', 19, 19, 'A sinusoidal supply has an r.m.s. voltage of 6.0 V. Calculate its peak-to-peak voltage.', NULL, 1, 'numeric'::answer_type, '16.97', 'V', false, NULL, false, NULL, 'V₀ = √2 × 6.0 = 8.49 V. Peak-to-peak = 2 × 8.485 = 17.0 V. Mark scheme (2 marks). C1: V₀ then × 2. A1: V_pp = 17.0 V.', 2),
('50d461cd-5db8-54f3-933c-b071033369f0', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '521788f0-c0f7-5ff9-94e2-bd6a8cd8daac', 'a-level', '27.1', '9702 coursebook 27.1 · Alternating current and r.m.s. values', 20, 20, 'A square-wave voltage switches between +V₀ and −V₀ with equal times at each. What is its r.m.s. value?', NULL, 1, 'multiple_choice'::answer_type, 'V₀', NULL, false, NULL, false, NULL, 'V² is always V₀², so the r.m.s. value is V₀. Mark scheme (1 mark). B1: A (V₀).', 1),
('b0e629f5-4276-5edd-99d5-75d0cdf2e05a', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '521788f0-c0f7-5ff9-94e2-bd6a8cd8daac', 'a-level', '27.1', '9702 coursebook 27.1 · Alternating current and r.m.s. values', 21, 21, 'A sinusoidal current has an r.m.s. value of 0.50 A. Calculate its peak value.', NULL, 1, 'numeric'::answer_type, '0.7071', 'A', false, NULL, false, NULL, 'I₀ = √2 × 0.50 = 0.707 A. Mark scheme (1 mark). A1: I₀ = 0.707 A.', 1),
('3ace58d0-aba8-5050-965b-6052ce93dea8', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '521788f0-c0f7-5ff9-94e2-bd6a8cd8daac', 'a-level', '27.1', '9702 coursebook 27.1 · Alternating current and r.m.s. values', 22, 22, 'Which expression gives the mean power dissipated in a resistor R by a sinusoidal current?', NULL, 1, 'multiple_choice'::answer_type, 'I_rms²R', NULL, false, NULL, false, NULL, 'Mean power = I_rms²R = ½I₀²R. Mark scheme (1 mark). B1: D (I_rms²R).', 1),
('568802d6-b3bd-5019-bbce-def0653f74e3', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '521788f0-c0f7-5ff9-94e2-bd6a8cd8daac', 'a-level', '27.1', '9702 coursebook 27.1 · Alternating current and r.m.s. values', 23, 23, 'A sinusoidal current of peak value 2.0 A flows through a 10 Ω resistor. Calculate the mean power.', NULL, 1, 'numeric'::answer_type, '20', 'W', false, NULL, false, NULL, 'P = ½I₀²R = 0.5 × 2.0² × 10 = 20 W. Mark scheme (2 marks). C1: ½I₀²R. A1: P = 20 W.', 2),
('d8804c2b-8384-51be-8a96-555e4e775e9a', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '521788f0-c0f7-5ff9-94e2-bd6a8cd8daac', 'a-level', '27.1', '9702 coursebook 27.1 · Alternating current and r.m.s. values', 24, 24, 'How does the instantaneous power in a resistor connected to a sinusoidal supply vary?', NULL, 1, 'multiple_choice'::answer_type, 'Between zero and twice the mean power', NULL, false, NULL, false, NULL, 'P = I₀²R sin²ωt varies from 0 to I₀²R = 2P_mean. Mark scheme (1 mark). B1: B (Between zero and twice the mean power).', 1),
('fb31f983-c075-58c0-bd8c-7b4a540d4545', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '521788f0-c0f7-5ff9-94e2-bd6a8cd8daac', 'a-level', '27.1', '9702 coursebook 27.1 · Alternating current and r.m.s. values', 25, 25, 'A lamp of resistance 240 Ω dissipates a mean power of 60 W on an a.c. supply. Calculate the r.m.s. voltage across it.', NULL, 2, 'numeric'::answer_type, '120', 'V', false, NULL, false, NULL, 'V_rms = √(PR) = √(60 × 240) = 120 V. Mark scheme (3 marks). C1: P = V_rms²/R. C1: rearranged. A1: V_rms = 120 V.', 3),
('b672b42c-c937-51c4-b208-e524458f7cde', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '521788f0-c0f7-5ff9-94e2-bd6a8cd8daac', 'a-level', '27.1', '9702 coursebook 27.1 · Alternating current and r.m.s. values', 26, 26, 'An r.m.s. current of 2.0 A flows through a 15 Ω resistor. Calculate the peak voltage across it.', NULL, 2, 'numeric'::answer_type, '42.43', 'V', false, NULL, false, NULL, 'V_rms = 2.0 × 15 = 30 V. V₀ = √2 × 30 = 42.4 V. Mark scheme (3 marks). C1: V_rms = I_rms R. C1: × √2. A1: V₀ = 42.4 V.', 3),
('4914f17d-9839-51cb-b46f-531c50fdc962', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '521788f0-c0f7-5ff9-94e2-bd6a8cd8daac', 'a-level', '27.1', '9702 coursebook 27.1 · Alternating current and r.m.s. values', 27, 27, 'A resistor is connected first to a 10 V d.c. supply and then to a sinusoidal supply of peak 10 V. Which statement is correct?', NULL, 2, 'multiple_choice'::answer_type, 'The d.c. supply gives twice the mean power', NULL, false, NULL, false, NULL, 'The a.c. has V_rms = 7.07 V, so P is (7.07/10)² = ½ of the d.c. power. Mark scheme (3 marks). C1: V_rms = V₀/√2. C1: P ∝ V². A1: C (The d.c. supply gives twice the mean power).', 3),
('fecc3df9-240b-5573-9dfe-2f4d54316656', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '521788f0-c0f7-5ff9-94e2-bd6a8cd8daac', 'a-level', '27.1', '9702 coursebook 27.1 · Alternating current and r.m.s. values', 28, 28, 'A heater is connected to a sinusoidal supply of peak voltage 340 V. Calculate the steady d.c. voltage that would give the same mean power.', NULL, 2, 'numeric'::answer_type, '240.4', 'V', false, NULL, false, NULL, 'Equivalent d.c. = V_rms = 340 ÷ √2 = 240 V. Mark scheme (4 marks). M1: d.c. equivalent is the r.m.s. value. C1: V_rms = V₀/√2. C1: value. A1: V = 240 V.', 4),
('c2dbd804-733c-58fb-aa4f-50eb6f17456c', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '521788f0-c0f7-5ff9-94e2-bd6a8cd8daac', 'a-level', '27.1', '9702 coursebook 27.1 · Alternating current and r.m.s. values', 29, 29, 'A voltage is +4.0 V for half of each cycle and 0 V for the other half. Calculate its r.m.s. value.', NULL, 2, 'numeric'::answer_type, '2.828', 'V', false, NULL, false, NULL, 'Mean of V² = (4.0² + 0) ÷ 2 = 8.0 V². V_rms = √8.0 = 2.83 V. Mark scheme (3 marks). C1: mean of the squares. C1: square root. A1: V_rms = 2.83 V.', 3),
('45e708ae-745a-5be8-8ae6-757e3602318c', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '521788f0-c0f7-5ff9-94e2-bd6a8cd8daac', 'a-level', '27.1', '9702 coursebook 27.1 · Alternating current and r.m.s. values', 30, 30, 'The peak voltage of a sinusoidal supply across a resistor is doubled. What happens to the r.m.s. voltage and to the mean power?', NULL, 2, 'multiple_choice'::answer_type, 'The r.m.s. voltage doubles and the mean power quadruples', NULL, false, NULL, false, NULL, 'V_rms ∝ V₀ and P ∝ V_rms². Mark scheme (3 marks). C1: V_rms ∝ V₀. C1: P ∝ V². A1: A (The r.m.s. voltage doubles and the mean power quadruples).', 3),
('e03e0a6d-0bc8-5a70-b330-0d56f5af3c69', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '521788f0-c0f7-5ff9-94e2-bd6a8cd8daac', 'a-level', '27.1', '9702 coursebook 27.1 · Alternating current and r.m.s. values', 31, 31, 'An r.m.s. current of 3.0 A flows through a 20 Ω resistor for 1.0 hour. Calculate the energy dissipated.', NULL, 2, 'numeric'::answer_type, '6.48e5', 'J', false, NULL, false, NULL, 'P = 3.0² × 20 = 180 W. E = Pt = 180 × 3600 = 6.48 × 10⁵ J. Mark scheme (3 marks). C1: P = I_rms²R. C1: E = Pt. A1: E = 6.48 × 10⁵ J.', 3),
('4831b02a-3505-58d7-998b-3024376f58c7', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '521788f0-c0f7-5ff9-94e2-bd6a8cd8daac', 'a-level', '27.1', '9702 coursebook 27.1 · Alternating current and r.m.s. values', 32, 32, 'For a triangular waveform, I_rms = I₀/√3. Calculate the r.m.s. value of a triangular current of peak 6.0 A.', NULL, 2, 'numeric'::answer_type, '3.464', 'A', false, NULL, false, NULL, 'I_rms = 6.0 ÷ √3 = 3.46 A. Mark scheme (4 marks). C1: formula. C1: substitution. B1: differs from the sine-wave value 4.24 A. A1: I_rms = 3.46 A.', 4),
('aca0ee51-f65f-5677-a436-0b8f350b207f', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '521788f0-c0f7-5ff9-94e2-bd6a8cd8daac', 'a-level', '27.1', '9702 coursebook 27.1 · Alternating current and r.m.s. values', 33, 33, 'The mean of an alternating current over a cycle is zero, yet it heats a resistor. Why?', NULL, 2, 'multiple_choice'::answer_type, 'Heating depends on I², which is positive for either direction of current', NULL, false, NULL, false, NULL, 'P = I²R ≥ 0 at every instant. Mark scheme (3 marks). C1: P ∝ I². C1: always positive. A1: D (Heating depends on I², which is positive for either direction of current).', 3),
('b9292727-0119-564b-bb8d-075e01fb0aa7', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '521788f0-c0f7-5ff9-94e2-bd6a8cd8daac', 'a-level', '27.1', '9702 coursebook 27.1 · Alternating current and r.m.s. values', 34, 34, 'An a.c. supply has an r.m.s. voltage of 12 V and drives an r.m.s. current of 0.50 A through a resistor. Calculate the peak power.', NULL, 2, 'numeric'::answer_type, '12', 'W', false, NULL, false, NULL, 'Mean power = 12 × 0.50 = 6.0 W. Peak power = 2 × 6.0 = 12 W. Mark scheme (3 marks). C1: P = V_rms I_rms. C1: peak = 2 × mean. A1: P₀ = 12 W.', 3),
('0d057a8c-593a-56cc-a6aa-388b83177e7e', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '521788f0-c0f7-5ff9-94e2-bd6a8cd8daac', 'a-level', '27.1', '9702 coursebook 27.1 · Alternating current and r.m.s. values', 35, 35, 'A 50 V r.m.s. supply drives a sinusoidal current of peak 1.5 A through a resistor. Calculate its resistance.', NULL, 2, 'numeric'::answer_type, '47.14', 'Ω', false, NULL, false, NULL, 'I_rms = 1.5 ÷ √2 = 1.06 A. R = 50 ÷ 1.061 = 47.1 Ω. Mark scheme (3 marks). C1: I_rms. C1: R = V_rms/I_rms. A1: R = 47.1 Ω.', 3),
('3cb0736b-0253-5683-82d3-c6a3bfe6c2da', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '521788f0-c0f7-5ff9-94e2-bd6a8cd8daac', 'a-level', '27.1', '9702 coursebook 27.1 · Alternating current and r.m.s. values', 36, 36, 'Which describes a graph of I² against time for a sinusoidal current of peak I₀?', NULL, 2, 'multiple_choice'::answer_type, 'It oscillates between 0 and I₀² at twice the supply frequency, with a mean of I₀²/2', NULL, false, NULL, false, NULL, 'sin² ωt = ½(1 − cos 2ωt). Mark scheme (4 marks). C1: always positive. C1: double frequency. C1: mean I₀²/2. A1: B (It oscillates between 0 and I₀² at twice the supply frequency, with a mean of I₀²/2).', 4),
('5f7e2d7d-9c6c-5bac-9ee1-73c64877f0d1', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '521788f0-c0f7-5ff9-94e2-bd6a8cd8daac', 'a-level', '27.1', '9702 coursebook 27.1 · Alternating current and r.m.s. values', 37, 37, 'A resistor is connected to a sinusoidal supply of peak 10 V and then to a 6.0 V d.c. supply. Calculate (mean a.c. power) ÷ (d.c. power).', NULL, 2, 'numeric'::answer_type, '1.389', NULL, false, NULL, false, NULL, 'P ∝ V²: ratio = (10 ÷ √2)² ÷ 6.0² = 50 ÷ 36 = 1.39. Mark scheme (3 marks). C1: V_rms = 7.07 V. C1: ratio of squares. A1: ratio = 1.39.', 3),
('c74b459f-0f0f-5551-8210-e20317d94516', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '521788f0-c0f7-5ff9-94e2-bd6a8cd8daac', 'a-level', '27.1', '9702 coursebook 27.1 · Alternating current and r.m.s. values', 38, 38, 'How many times per second does the direction of a 50 Hz alternating current reverse?', NULL, 2, 'numeric'::answer_type, '100', NULL, false, NULL, false, NULL, 'The current reverses twice in each cycle: 2 × 50 = 100 times per second. Mark scheme (3 marks). C1: two reversals per cycle. C1: value. A1: reversals = 100.', 3),
('8cbc702f-eda1-5be0-93fe-984a99c944c5', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '521788f0-c0f7-5ff9-94e2-bd6a8cd8daac', 'a-level', '27.1', '9702 coursebook 27.1 · Alternating current and r.m.s. values', 39, 39, 'A voltmeter connected to the mains reads 230 V. What does this reading represent?', NULL, 2, 'multiple_choice'::answer_type, 'The r.m.s. voltage', NULL, false, NULL, false, NULL, 'a.c. meters are calibrated to read r.m.s. values. Mark scheme (3 marks). C1: meters read r.m.s. C1: peak is 325 V. A1: C (The r.m.s. voltage).', 3),
('0ca9b233-1c3c-5d89-9d6c-739d8324632f', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '521788f0-c0f7-5ff9-94e2-bd6a8cd8daac', 'a-level', '27.1', '9702 coursebook 27.1 · Alternating current and r.m.s. values', 40, 40, 'A sinusoidal current of peak 3.0 A flows through an 8.0 Ω resistor. (a) Calculate the maximum instantaneous power. (b) Calculate the mean power. (c) Calculate the r.m.s. current. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '36', 'W', false, NULL, false, NULL, '(a) P₀ = I₀²R = 3.0² × 8.0 = 72 W. (b) Mean P = 0.5 × 72 = 36 W. (c) I_rms = 3.0 ÷ √2 = 2.12 A; check I_rms²R = 36 W. Mark scheme (5 marks). C1: P₀ = I₀²R. M1: mean = ½P₀. C1: value. C1: I_rms. A1: P = 36 W.', 5),
('fee8f1f5-4a19-5791-a547-801316251081', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '521788f0-c0f7-5ff9-94e2-bd6a8cd8daac', 'a-level', '27.1', '9702 coursebook 27.1 · Alternating current and r.m.s. values', 41, 41, 'A voltage is +6.0 V for 2.0 ms and −2.0 V for the next 2.0 ms, repeating. (a) Calculate the mean voltage. (b) Calculate the mean of V². (c) Calculate the r.m.s. voltage. (d) Calculate the mean power it delivers to a 10 Ω resistor. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '4.472', 'V', false, NULL, false, NULL, '(a) Mean = (6.0 − 2.0) ÷ 2 = 2.0 V. (b) Mean of V² = (6.0² + 2.0²) ÷ 2 = 20 V². (c) V_rms = √20 = 4.47 V. (d) P = V_rms²/R = 20 ÷ 10 = 2.0 W. Mark scheme (6 marks). C1: mean. C1: mean of squares. C1: square root. C1: P = V_rms²/R. B1: r.m.s. ≠ mean. A1: V_rms = 4.47 V.', 6),
('8e86bc0e-5a69-5336-8e02-686a7911f0a8', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '521788f0-c0f7-5ff9-94e2-bd6a8cd8daac', 'a-level', '27.1', '9702 coursebook 27.1 · Alternating current and r.m.s. values', 42, 42, 'A 2.8 kW kettle runs on a 230 V r.m.s. supply. (a) Calculate the r.m.s. current. (b) Calculate the peak current. (c) Explain why a 13 A fuse is suitable even though the peak current is larger than 13 A. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '17.22', 'A', false, NULL, false, NULL, '(a) I_rms = 2800 ÷ 230 = 12.2 A. (b) I₀ = √2 × 12.17 = 17.2 A. (c) Fuses respond to heating, which depends on the r.m.s. current, 12.2 A, below 13 A. Mark scheme (5 marks). C1: I = P/V. C1: × √2. C1: value. B1: heating depends on r.m.s. A1: I₀ = 17.2 A.', 5),
('5f4c6ee3-88c5-5f57-9aef-581fa12b6af8', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '521788f0-c0f7-5ff9-94e2-bd6a8cd8daac', 'a-level', '27.1', '9702 coursebook 27.1 · Alternating current and r.m.s. values', 43, 43, 'An oscilloscope shows a sinusoidal trace. The Y-gain is 5.0 V per division and the peak is 3.4 divisions above the centre line. The time-base is 2.0 ms per division and one cycle spans 5.0 divisions. (a) Calculate the peak voltage. (b) Calculate the r.m.s. voltage. (c) Calculate the frequency. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '12.02', 'V', false, NULL, false, NULL, '(a) V₀ = 3.4 × 5.0 = 17 V. (b) V_rms = 17 ÷ √2 = 12.0 V. (c) T = 5.0 × 2.0 = 10 ms, so f = 1 ÷ 0.010 = 100 Hz. Mark scheme (6 marks). C1: divisions × Y-gain. C1: V_rms. C1: period from time-base. C1: f = 1/T. B1: reading taken from centre line. A1: V_rms = 12.0 V.', 6),
('a74452eb-3240-56da-848e-8e654de3e2b7', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '521788f0-c0f7-5ff9-94e2-bd6a8cd8daac', 'a-level', '27.1', '9702 coursebook 27.1 · Alternating current and r.m.s. values', 44, 44, 'A heating element is rated at 2.0 kW on a 230 V r.m.s. supply. (a) State the power on a 230 V d.c. supply. (b) Calculate the power on a sinusoidal supply of peak value 230 V. Give only the answer to (b), in kW.', NULL, 3, 'numeric'::answer_type, '1 kW', 'kW', false, NULL, false, NULL, '(a) 2.0 kW: 230 V r.m.s. has the same heating effect as 230 V d.c. (b) V_rms = 230 ÷ √2, so P ∝ V² is halved: P = 2.0 ÷ 2 = 1.0 kW. Mark scheme (5 marks). B1: r.m.s. equals d.c. equivalent. M1: P ∝ V_rms². C1: factor ½. C1: value. A1: P = 1.0 kW.', 5),
('b1f6fa94-c3c6-53ad-aa88-0da6d6daa5f7', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '521788f0-c0f7-5ff9-94e2-bd6a8cd8daac', 'a-level', '27.1', '9702 coursebook 27.1 · Alternating current and r.m.s. values', 45, 45, 'A 3.0 kW heater runs for 4.0 hours a day for 30 days. (a) Calculate the energy used, in kW h. (b) Calculate the energy in joules. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '1.296e9', 'J', false, NULL, false, NULL, '(a) E = 3.0 × 4.0 × 30 = 360 kW h. (b) E = 3.0 × 10³ × 4.0 × 3600 × 30 = 1.296 × 10⁹ J. Mark scheme (5 marks). C1: kW h. C1: hours to seconds. C1: value. B1: 1 kW h = 3.6 MJ. A1: E = 1.30 × 10⁹ J.', 5),
('20b5e9a7-1991-5cc1-a88c-6da2785e174f', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '521788f0-c0f7-5ff9-94e2-bd6a8cd8daac', 'a-level', '27.1', '9702 coursebook 27.1 · Alternating current and r.m.s. values', 46, 46, 'A half-wave rectified sinusoidal voltage of peak V₀ has an r.m.s. value of V₀/2. (a) Explain why this is less than V₀/√2. (b) Calculate the mean power it delivers to a 50 Ω resistor when V₀ = 20 V. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '2', 'W', false, NULL, false, NULL, '(a) One half of every cycle is missing, so the mean of V² is halved. (b) V_rms = 20 ÷ 2 = 10 V; P = 10² ÷ 50 = 2.0 W. Mark scheme (5 marks). B1: half the cycles removed. C1: V_rms = 10 V. M1: P = V_rms²/R. C1: value. A1: P = 2.0 W.', 5),
('4f8d2119-b6b4-5458-bb0a-0a0dafabb727', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '521788f0-c0f7-5ff9-94e2-bd6a8cd8daac', 'a-level', '27.1', '9702 coursebook 27.1 · Alternating current and r.m.s. values', 47, 47, 'The current in a resistor is I = 4.0 sin(100πt), with I in A and t in s. (a) State the peak current and the frequency. (b) Calculate the r.m.s. current. (c) Calculate the mean power in a 5.0 Ω resistor. (d) Calculate the current at t = 2.5 ms. Give only the answer to (d).', NULL, 3, 'numeric'::answer_type, '2.828', 'A', false, NULL, false, NULL, '(a) I₀ = 4.0 A; ω = 100π, so f = 50 Hz. (b) I_rms = 4.0 ÷ √2 = 2.83 A. (c) P = ½ × 4.0² × 5.0 = 40 W. (d) ωt = 100π × 2.5 × 10⁻³ = π/4 rad, which is 45°: I = 4.0 × sin 45° = 2.83 A. Mark scheme (6 marks). C1: I₀ and f. C1: I_rms. C1: mean power. M1: ωt in degrees. C1: instantaneous value. A1: I = 2.83 A.', 6),
('c7382378-7460-5823-bfa2-3dbdd9977cfb', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '521788f0-c0f7-5ff9-94e2-bd6a8cd8daac', 'a-level', '27.1', '9702 coursebook 27.1 · Alternating current and r.m.s. values', 48, 48, 'The UK mains is 230 V r.m.s. and the North American mains is 120 V r.m.s. (a) Calculate both peak voltages. (b) Calculate (power in a resistor on UK mains) ÷ (power in the same resistor on North American mains). Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '3.674', NULL, false, NULL, false, NULL, '(a) 230 × √2 = 325 V and 120 × √2 = 170 V. (b) P ∝ V_rms²: ratio = (230 ÷ 120)² = 3.67. Mark scheme (5 marks). C1: peak values. M1: P ∝ V². C1: ratio. B1: r.m.s. values used. A1: ratio = 3.67.', 5),
('75c3445c-e5b3-571b-8a3e-5f69b75cf9d3', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '521788f0-c0f7-5ff9-94e2-bd6a8cd8daac', 'a-level', '27.1', '9702 coursebook 27.1 · Alternating current and r.m.s. values', 49, 49, '(a) Show that the mean power delivered to a resistor by a sinusoidal supply is ½V₀I₀. (b) Calculate the mean power when V₀ = 170 V and I₀ = 2.0 A. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '170', 'W', false, NULL, false, NULL, '(a) P = V_rms I_rms = (V₀/√2)(I₀/√2) = ½V₀I₀. (b) P = 0.5 × 170 × 2.0 = 170 W. Mark scheme (5 marks). M1: use r.m.s. values. B1: ½V₀I₀ shown. C1: substitution. C1: value. A1: P = 170 W.', 5),
('585a6054-1c33-51c9-973f-b628ce608a4b', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '521788f0-c0f7-5ff9-94e2-bd6a8cd8daac', 'a-level', '27.1', '9702 coursebook 27.1 · Alternating current and r.m.s. values', 50, 50, 'A current of 3.0 A flows for 0.010 s and is then zero for 0.030 s, repeating. (a) Calculate the fraction of each cycle for which the current flows. (b) Calculate the r.m.s. current. (c) Calculate the mean power in a 20 Ω resistor. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '1.5', 'A', false, NULL, false, NULL, '(a) 0.010 ÷ 0.040 = 0.25. (b) Mean of I² = 0.25 × 3.0² = 2.25 A², so I_rms = √2.25 = 1.5 A. (c) P = 2.25 × 20 = 45 W. Mark scheme (6 marks). C1: fraction. C1: mean of I². C1: square root. C1: P = I_rms²R. B1: r.m.s. not mean. A1: I_rms = 1.5 A.', 6)
