('03028e5a-c393-5b0b-898c-b4bfd701a29e', '8cbc702f-eda1-5be0-93fe-984a99c944c5', 'The mean voltage', 'D', false, 3)
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points) VALUES
('3c9bc4e1-42e1-50e8-be8a-6e6fe70ceebf', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '1dcc934a-cbaa-4233-91fd-46dc3b235528', 'a-level', '27.2', '9702 coursebook 27.2 · Alternating voltages', 7, 7, 'Calculate the angular frequency of a 50 Hz supply.', NULL, 1, 'numeric'::answer_type, '314.2', 'rad s⁻¹', false, NULL, false, NULL, 'ω = 2πf = 2π × 50 = 314 rad s⁻¹. Mark scheme (2 marks). C1: ω = 2πf. A1: ω = 314 rad s⁻¹.', 2),
('8d1f6df7-5457-5782-922d-483f172027ea', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '1dcc934a-cbaa-4233-91fd-46dc3b235528', 'a-level', '27.2', '9702 coursebook 27.2 · Alternating voltages', 8, 8, 'In the equation V = V₀ sin ωt, what does V₀ represent?', NULL, 1, 'multiple_choice'::answer_type, 'The peak voltage', NULL, false, NULL, false, NULL, 'V₀ is the largest value reached in each cycle. Mark scheme (1 mark). B1: C (The peak voltage).', 1),
('380ce4d2-986d-5d76-bc79-9cf089a25744', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '1dcc934a-cbaa-4233-91fd-46dc3b235528', 'a-level', '27.2', '9702 coursebook 27.2 · Alternating voltages', 9, 9, 'An alternating voltage has ω = 100π rad s⁻¹. Calculate its period.', NULL, 1, 'numeric'::answer_type, '0.02', 's', false, NULL, false, NULL, 'T = 2π/ω = 2π ÷ 100π = 0.020 s. Mark scheme (2 marks). C1: T = 2π/ω. A1: T = 0.020 s.', 2),
('c66c9315-0d67-5479-b074-1741758d405a', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '1dcc934a-cbaa-4233-91fd-46dc3b235528', 'a-level', '27.2', '9702 coursebook 27.2 · Alternating voltages', 10, 10, 'An oscilloscope trace has a peak 2.5 divisions above the centre line, with the Y-gain at 2.0 V per division. Calculate the peak voltage.', NULL, 1, 'numeric'::answer_type, '5', 'V', false, NULL, false, NULL, 'V₀ = 2.5 × 2.0 = 5.0 V. Mark scheme (2 marks). C1: divisions × Y-gain. A1: V₀ = 5.0 V.', 2),
('5f38feb2-e7a5-5e8c-a73f-f71ec398c864', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '1dcc934a-cbaa-4233-91fd-46dc3b235528', 'a-level', '27.2', '9702 coursebook 27.2 · Alternating voltages', 11, 11, 'What does the time-base control of an oscilloscope set?', NULL, 1, 'multiple_choice'::answer_type, 'The time represented by each horizontal division', NULL, false, NULL, false, NULL, 'It sets how fast the spot sweeps across the screen. Mark scheme (1 mark). B1: A (The time represented by each horizontal division).', 1),
('4c74aaea-14ce-57c6-a0eb-1a172d0b82e4', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '1dcc934a-cbaa-4233-91fd-46dc3b235528', 'a-level', '27.2', '9702 coursebook 27.2 · Alternating voltages', 12, 12, 'One cycle of a trace spans 4.0 divisions with the time-base at 5.0 ms per division. Calculate the frequency.', NULL, 1, 'numeric'::answer_type, '50', 'Hz', false, NULL, false, NULL, 'T = 4.0 × 5.0 = 20 ms. f = 1 ÷ 0.020 = 50 Hz. Mark scheme (2 marks). C1: T from divisions. A1: f = 50 Hz.', 2),
('98312416-287a-5385-8b66-5cba2ca66561', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '1dcc934a-cbaa-4233-91fd-46dc3b235528', 'a-level', '27.2', '9702 coursebook 27.2 · Alternating voltages', 13, 13, 'What is the peak-to-peak voltage of a sinusoidal supply of peak V₀?', NULL, 1, 'multiple_choice'::answer_type, '2V₀', NULL, false, NULL, false, NULL, 'It is measured from the top of a crest to the bottom of a trough. Mark scheme (1 mark). B1: D (2V₀).', 1),
('603e4f67-bf8d-5ddc-ab29-2a6f3ee0411b', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '1dcc934a-cbaa-4233-91fd-46dc3b235528', 'a-level', '27.2', '9702 coursebook 27.2 · Alternating voltages', 14, 14, 'For V = 12 sin ωt (in volts), calculate V when ωt = 30°.', NULL, 1, 'numeric'::answer_type, '6', 'V', false, NULL, false, NULL, 'V = 12 × sin 30° = 6.0 V. Mark scheme (2 marks). C1: substitution. A1: V = 6.0 V.', 2),
('1909e296-56d8-57f6-866e-62ed20f9312b', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '1dcc934a-cbaa-4233-91fd-46dc3b235528', 'a-level', '27.2', '9702 coursebook 27.2 · Alternating voltages', 15, 15, 'For V = V₀ sin ωt, what is the voltage a quarter of a period after t = 0?', NULL, 1, 'multiple_choice'::answer_type, 'V₀', NULL, false, NULL, false, NULL, 'ωt = π/2 at t = T/4, and sin 90° = 1. Mark scheme (1 mark). B1: B (V₀).', 1),
('de78061b-1c4d-5bad-bbd6-5e6e251d0446', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '1dcc934a-cbaa-4233-91fd-46dc3b235528', 'a-level', '27.2', '9702 coursebook 27.2 · Alternating voltages', 16, 16, 'An oscilloscope shows a peak of 3.0 divisions with the Y-gain at 5.0 V per division. Calculate the r.m.s. voltage.', NULL, 1, 'numeric'::answer_type, '10.61', 'V', false, NULL, false, NULL, 'V₀ = 3.0 × 5.0 = 15 V. V_rms = 15 ÷ √2 = 10.6 V. Mark scheme (2 marks). C1: V₀ then ÷ √2. A1: V_rms = 10.6 V.', 2),
('6d2c3852-0a62-5f2a-b402-d82b0c5ef470', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '1dcc934a-cbaa-4233-91fd-46dc3b235528', 'a-level', '27.2', '9702 coursebook 27.2 · Alternating voltages', 17, 17, 'The frequency of a signal is doubled while the time-base setting is unchanged. What happens to the trace?', NULL, 1, 'multiple_choice'::answer_type, 'Twice as many cycles appear across the screen', NULL, false, NULL, false, NULL, 'Each cycle takes half as long, so it occupies half as many divisions. Mark scheme (1 mark). B1: C (Twice as many cycles appear across the screen).', 1),
('216cbb4e-0061-5878-af3d-0f703460070f', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '1dcc934a-cbaa-4233-91fd-46dc3b235528', 'a-level', '27.2', '9702 coursebook 27.2 · Alternating voltages', 18, 18, 'An alternating voltage is V = 325 sin(314t). Calculate its frequency.', NULL, 1, 'numeric'::answer_type, '49.97', 'Hz', false, NULL, false, NULL, 'f = ω/2π = 314 ÷ 2π = 50.0 Hz. Mark scheme (2 marks). C1: f = ω/2π. A1: f = 50.0 Hz.', 2),
('d155b2e3-8421-5505-aac6-79a1e0e51b7e', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '1dcc934a-cbaa-4233-91fd-46dc3b235528', 'a-level', '27.2', '9702 coursebook 27.2 · Alternating voltages', 19, 19, 'The Y-gain of an oscilloscope is changed from 5 V per division to 2 V per division. What happens to the trace?', NULL, 1, 'multiple_choice'::answer_type, 'It becomes taller', NULL, false, NULL, false, NULL, 'Each volt now occupies more of the screen vertically. Mark scheme (1 mark). B1: A (It becomes taller).', 1),
('05c294aa-3ba7-58f0-b6b3-2424fd345d9a', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '1dcc934a-cbaa-4233-91fd-46dc3b235528', 'a-level', '27.2', '9702 coursebook 27.2 · Alternating voltages', 20, 20, 'A sinusoidal voltage has a peak of 9.0 V. What is its peak-to-peak value?', NULL, 1, 'numeric'::answer_type, '18', 'V', false, NULL, false, NULL, 'V_pp = 2 × 9.0 = 18 V. Mark scheme (1 mark). A1: V_pp = 18 V.', 1),
('0f503757-f1b5-592a-88c9-111bcafccb0c', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '1dcc934a-cbaa-4233-91fd-46dc3b235528', 'a-level', '27.2', '9702 coursebook 27.2 · Alternating voltages', 21, 21, 'Which statement about a sinusoidal alternating voltage is correct?', NULL, 1, 'multiple_choice'::answer_type, 'The positive and negative half cycles have the same shape and size', NULL, false, NULL, false, NULL, 'A sine wave is symmetrical about the time axis. Mark scheme (1 mark). B1: D (The positive and negative half cycles have the same shape and size).', 1),
('7f81c62a-f700-5120-a87c-08ecc8877a29', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '1dcc934a-cbaa-4233-91fd-46dc3b235528', 'a-level', '27.2', '9702 coursebook 27.2 · Alternating voltages', 22, 22, 'An oscilloscope screen is 10 divisions wide, with the time-base at 2.0 ms per division. A 200 Hz signal is displayed. How many complete cycles appear?', NULL, 1, 'numeric'::answer_type, '4', NULL, false, NULL, false, NULL, 'Screen time = 10 × 2.0 = 20 ms. Cycles = 0.020 × 200 = 4.0. Mark scheme (2 marks). C1: total time × f. A1: cycles = 4.0.', 2),
('cec51ab7-4667-598c-9dcc-88ab4917fdab', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '1dcc934a-cbaa-4233-91fd-46dc3b235528', 'a-level', '27.2', '9702 coursebook 27.2 · Alternating voltages', 23, 23, 'A sinusoidal voltage of peak 20 V and frequency 50 Hz is zero at t = 0 and rising. Calculate the voltage at t = 3.0 ms.', NULL, 2, 'numeric'::answer_type, '16.18', 'V', false, NULL, false, NULL, 'ωt = 2π × 50 × 3.0 × 10⁻³ = 0.942 rad, which is 54.0°. V = 20 × sin 54.0° = 16.2 V. Mark scheme (3 marks). C1: ωt. C1: V = V₀ sin ωt. A1: V = 16.2 V.', 3),
('2eaea863-f0c8-5c37-bd02-2933be5fc0d1', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '1dcc934a-cbaa-4233-91fd-46dc3b235528', 'a-level', '27.2', '9702 coursebook 27.2 · Alternating voltages', 24, 24, 'A 50 Hz sinusoidal voltage starts at zero and rises. Calculate the time it takes to first reach half its peak value, in ms.', NULL, 2, 'numeric'::answer_type, '1.667 ms', 'ms', false, NULL, false, NULL, 'sin ωt = 0.50 gives ωt = 30°, which is one twelfth of a cycle. t = T/12 = 0.020 ÷ 12 = 0.00167 s. In ms: 0.001667 × 1000 = 1.67. Mark scheme (3 marks). C1: ωt = 30°. C1: fraction of period. A1: t = 1.67 ms.', 3),
('5810ca41-104e-5861-bc4a-6a1f8ab63746', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '1dcc934a-cbaa-4233-91fd-46dc3b235528', 'a-level', '27.2', '9702 coursebook 27.2 · Alternating voltages', 25, 25, 'Two sinusoidal signals of the same frequency are displayed together. One reaches its peak a quarter of a period after the other. What is their phase difference?', NULL, 2, 'multiple_choice'::answer_type, '90°', NULL, false, NULL, false, NULL, 'A full period is 360°, so a quarter period is 90°. Mark scheme (3 marks). C1: fraction of period. C1: × 360°. A1: B (90°).', 3),
('f3c1f6bc-ddc3-5898-94a5-9098542d8755', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '1dcc934a-cbaa-4233-91fd-46dc3b235528', 'a-level', '27.2', '9702 coursebook 27.2 · Alternating voltages', 26, 26, 'A trace has a peak-to-peak height of 6.4 divisions with the Y-gain at 0.50 V per division. Calculate the r.m.s. voltage.', NULL, 2, 'numeric'::answer_type, '1.131', 'V', false, NULL, false, NULL, 'V_pp = 6.4 × 0.50 = 3.2 V. V₀ = 1.6 V. V_rms = 1.6 ÷ √2 = 1.13 V. Mark scheme (4 marks). C1: V_pp. C1: V₀ = V_pp/2. C1: ÷ √2. A1: V_rms = 1.13 V.', 4),
('9b8aa758-b0c4-5af8-b45a-2daa344425ae', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '1dcc934a-cbaa-4233-91fd-46dc3b235528', 'a-level', '27.2', '9702 coursebook 27.2 · Alternating voltages', 27, 27, 'A 12 V r.m.s. sinusoidal supply is to be displayed on an oscilloscope. Calculate its peak-to-peak voltage, which must fit on the screen.', NULL, 2, 'numeric'::answer_type, '33.94', 'V', false, NULL, false, NULL, 'V_pp = 2√2 × V_rms = 2 × √2 × 12 = 33.9 V. Mark scheme (3 marks). C1: V₀ = √2 V_rms. C1: × 2. A1: V_pp = 33.9 V.', 3),
('13817840-13e1-5fee-ad2c-d86fe30df118', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '1dcc934a-cbaa-4233-91fd-46dc3b235528', 'a-level', '27.2', '9702 coursebook 27.2 · Alternating voltages', 28, 28, 'For a sinusoidal supply connected across a resistor, what is the phase difference between the current and the voltage?', NULL, 2, 'multiple_choice'::answer_type, 'Zero: they reach their peaks together', NULL, false, NULL, false, NULL, 'I = V/R at every instant. Mark scheme (3 marks). C1: I ∝ V. C1: in phase. A1: C (Zero: they reach their peaks together).', 3),
('6b62ea45-6f25-5dcb-96dc-11b739b05d8d', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '1dcc934a-cbaa-4233-91fd-46dc3b235528', 'a-level', '27.2', '9702 coursebook 27.2 · Alternating voltages', 29, 29, 'What is the frequency of a signal described by V = 5.0 sin(2000t), with t in seconds?', NULL, 2, 'numeric'::answer_type, '318.3', 'Hz', false, NULL, false, NULL, 'f = ω/2π = 2000 ÷ 2π = 318 Hz. Mark scheme (3 marks). C1: ω = 2000 rad s⁻¹. C1: f = ω/2π. A1: f = 318 Hz.', 3),
('ce334555-6624-56c1-b9be-b6e23073a218', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '1dcc934a-cbaa-4233-91fd-46dc3b235528', 'a-level', '27.2', '9702 coursebook 27.2 · Alternating voltages', 30, 30, 'Calculate the time between successive peaks of a 60 Hz supply, in ms.', NULL, 2, 'numeric'::answer_type, '16.67 ms', 'ms', false, NULL, false, NULL, 'T = 1/f = 1 ÷ 60 = 0.0167 s. In ms: 0.01667 × 1000 = 16.7. Mark scheme (3 marks). C1: T = 1/f. C1: conversion. A1: T = 16.7 ms.', 3),
('a872c8de-39b5-5947-acbd-1a6cd825cdcf', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '1dcc934a-cbaa-4233-91fd-46dc3b235528', 'a-level', '27.2', '9702 coursebook 27.2 · Alternating voltages', 31, 31, 'The time-base of an oscilloscope is changed from 5 ms per division to 2 ms per division. What happens to a steady sinusoidal trace?', NULL, 2, 'multiple_choice'::answer_type, 'Each cycle spreads over more divisions, so fewer cycles are visible', NULL, false, NULL, false, NULL, 'Each division now represents less time. Mark scheme (3 marks). C1: less time per division. C1: cycles spread out. A1: A (Each cycle spreads over more divisions, so fewer cycles are visible).', 3),
('cf7fa2be-5034-54e3-bd60-d8649bc4bfec', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '1dcc934a-cbaa-4233-91fd-46dc3b235528', 'a-level', '27.2', '9702 coursebook 27.2 · Alternating voltages', 32, 32, 'In V = V₀ sin ωt, V₀ = 24 V. Find V one twelfth of a period after it crosses zero going upwards.', NULL, 2, 'numeric'::answer_type, '12', 'V', false, NULL, false, NULL, 'One twelfth of a period corresponds to ωt = 30°. V = 24 × sin 30° = 12 V. Mark scheme (3 marks). C1: ωt = 360° ÷ 12. C1: substitution. A1: V = 12 V.', 3),
('18504673-0ec4-543a-b99a-bcd5ee10a923', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '1dcc934a-cbaa-4233-91fd-46dc3b235528', 'a-level', '27.2', '9702 coursebook 27.2 · Alternating voltages', 33, 33, 'On an oscilloscope set to 2.0 V per division, a sine wave measures 8.4 divisions from crest to trough. Find its r.m.s. value.', NULL, 2, 'numeric'::answer_type, '5.94', 'V', false, NULL, false, NULL, 'V₀ = 8.4 × 2.0 ÷ 2 = 8.4 V. V_rms = 8.4 ÷ √2 = 5.94 V. Mark scheme (3 marks). C1: V₀. C1: ÷ √2. A1: V_rms = 5.94 V.', 3),
('58f787d9-61aa-54b3-9409-b4b145007352', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '1dcc934a-cbaa-4233-91fd-46dc3b235528', 'a-level', '27.2', '9702 coursebook 27.2 · Alternating voltages', 34, 34, 'Which equation describes a 50 Hz sinusoidal supply with an r.m.s. value of 230 V?', NULL, 2, 'multiple_choice'::answer_type, 'V = 325 sin(314t)', NULL, false, NULL, false, NULL, 'V₀ = 230√2 = 325 V and ω = 2π × 50 = 314 rad s⁻¹. Mark scheme (4 marks). C1: V₀ = √2 × 230. C1: ω = 2πf. C1: correct form. A1: D (V = 325 sin(314t)).', 4),
('42f54037-053b-5ad8-af39-6fda6a456f93', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '1dcc934a-cbaa-4233-91fd-46dc3b235528', 'a-level', '27.2', '9702 coursebook 27.2 · Alternating voltages', 35, 35, 'For a sinusoidal voltage, calculate (instantaneous value) ÷ (peak value) when ωt = 60°.', NULL, 2, 'numeric'::answer_type, '0.866', NULL, false, NULL, false, NULL, 'V/V₀ = sin 60° = 0.866. Mark scheme (3 marks). C1: V/V₀ = sin ωt. C1: value. A1: ratio = 0.866.', 3),
('4cea6094-c41a-558a-b347-34b0c5836fbb', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '1dcc934a-cbaa-4233-91fd-46dc3b235528', 'a-level', '27.2', '9702 coursebook 27.2 · Alternating voltages', 36, 36, 'Twelve complete cycles of a signal take 0.20 s. Calculate its frequency.', NULL, 2, 'numeric'::answer_type, '60', 'Hz', false, NULL, false, NULL, 'f = 12 ÷ 0.20 = 60 Hz. Mark scheme (3 marks). C1: cycles per second. C1: value. A1: f = 60 Hz.', 3),
('7e0b5a54-01ee-53f1-a05c-0d8571300462', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '1dcc934a-cbaa-4233-91fd-46dc3b235528', 'a-level', '27.2', '9702 coursebook 27.2 · Alternating voltages', 37, 37, 'An alternating voltage is connected to an oscilloscope with the time-base switched off. What appears on the screen?', NULL, 2, 'multiple_choice'::answer_type, 'A vertical line whose length is the peak-to-peak voltage', NULL, false, NULL, false, NULL, 'With no horizontal sweep, the spot moves only up and down. Mark scheme (3 marks). C1: no horizontal sweep. C1: line of length 2V₀. A1: B (A vertical line whose length is the peak-to-peak voltage).', 3),
('d056009f-74b5-54de-b728-a4f3e970d519', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '1dcc934a-cbaa-4233-91fd-46dc3b235528', 'a-level', '27.2', '9702 coursebook 27.2 · Alternating voltages', 38, 38, 'For V = 15 sin(100πt), with V in volts and t in seconds, calculate the time at which V first reaches 10 V, in ms.', NULL, 2, 'numeric'::answer_type, '2.323 ms', 'ms', false, NULL, false, NULL, 'sin(100πt) = 10 ÷ 15, so 100πt = sin⁻¹ 0.6667 = 41.8°, which is 0.730 rad. t = 0.7297 ÷ (100π) = 0.00232 s. In ms: 0.002323 × 1000 = 2.32. Mark scheme (4 marks). C1: sin⁻¹. M1: angle in radians. C1: t. A1: t = 2.32 ms.', 4),
('769c5898-db77-5231-93f3-faf8b000ad4f', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '1dcc934a-cbaa-4233-91fd-46dc3b235528', 'a-level', '27.2', '9702 coursebook 27.2 · Alternating voltages', 39, 39, 'An oscilloscope with a Y-gain of 2.0 V per division and a time-base of 0.50 ms per division shows a sine wave with a peak-to-peak height of 7.0 divisions and 4.0 divisions per cycle. (a) Calculate the peak voltage. (b) Calculate the r.m.s. voltage. (c) Calculate the frequency. (d) Write the equation for the voltage in the form V = V₀ sin ωt. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '500', 'Hz', false, NULL, false, NULL, '(a) V₀ = 7.0 × 2.0 ÷ 2 = 7.0 V. (b) V_rms = 7.0 ÷ √2 = 4.95 V. (c) T = 4.0 × 0.50 = 2.0 ms, so f = 1 ÷ 2.0 × 10⁻³ = 500 Hz. (d) ω = 2π × 500 = 3140 rad s⁻¹, so V = 7.0 sin(3140t). Mark scheme (6 marks). C1: V₀. C1: V_rms. C1: T. C1: f. B1: equation with ω. A1: f = 500 Hz.', 6),
('6955e981-05a9-57c2-8961-607acc424603', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '1dcc934a-cbaa-4233-91fd-46dc3b235528', 'a-level', '27.2', '9702 coursebook 27.2 · Alternating voltages', 40, 40, 'A voltage is V = 340 sin(100πt), in volts. (a) State the peak voltage and frequency. (b) Calculate V at t = 7.5 ms. (c) Explain the sign of your answer. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '240.4', 'V', false, NULL, false, NULL, '(a) 340 V and 50 Hz. (b) ωt = 100π × 7.5 × 10⁻³ = 2.36 rad, which is 135°: V = 340 × sin 135° = 240 V. (c) It is positive: 7.5 ms is still in the first half cycle (which lasts 10 ms), after the peak. Mark scheme (5 marks). C1: V₀ and f. M1: ωt in degrees. C1: value. B1: within first half cycle. A1: V = 240 V.', 5),
('2b0985b9-7f40-5213-b054-9b34bccadb0a', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '1dcc934a-cbaa-4233-91fd-46dc3b235528', 'a-level', '27.2', '9702 coursebook 27.2 · Alternating voltages', 41, 41, 'For a 50 Hz sinusoidal supply, (a) find the phase angles in the first half cycle at which |V| = 0.50V₀. (b) Hence find the fraction of each cycle for which |V| > 0.50V₀. (c) Calculate the total time per cycle for which |V| > 0.50V₀, in ms. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '13.33 ms', 'ms', false, NULL, false, NULL, '(a) sin θ = 0.50 at 30° and 150°. (b) |V| > 0.50V₀ from 30° to 150° in each half: 120° of every 180°, a fraction 120 ÷ 180 = 0.667. (c) Time = 0.6667 × 20 = 13.3 ms per 20 ms cycle. Mark scheme (6 marks). C1: 30° and 150°. M1: same in negative half. C1: fraction. C1: × period. B1: period 20 ms. A1: t = 13.3 ms.', 6),
('1d452eec-bb76-5884-9384-5c9095f19024', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '1dcc934a-cbaa-4233-91fd-46dc3b235528', 'a-level', '27.2', '9702 coursebook 27.2 · Alternating voltages', 42, 42, 'A dual-trace oscilloscope shows two sine waves of the same frequency, each cycle spanning 4.0 divisions. The peaks of one trace are 1.0 division to the right of the peaks of the other. (a) Calculate the phase difference in degrees. (b) State which trace leads. Give only the answer to (a).', NULL, 3, 'numeric'::answer_type, '90', '°', false, NULL, false, NULL, '(a) Phase difference = 1.0 ÷ 4.0 × 360° = 90°. (b) The trace whose peaks occur first (to the left) leads by 90°. Mark scheme (5 marks). C1: fraction of cycle. C1: × 360°. C1: value. B1: earlier trace leads. A1: φ = 90°.', 5),
('e5397d63-fcf2-51c1-b141-fbdc52d9c129', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '1dcc934a-cbaa-4233-91fd-46dc3b235528', 'a-level', '27.2', '9702 coursebook 27.2 · Alternating voltages', 43, 43, 'A neon lamp lights only when the p.d. across it is more than 200 V. It is connected to the 230 V r.m.s. mains. (a) Calculate the peak mains voltage. (b) Calculate the phase angle at which the lamp first lights in each half cycle. (c) Calculate the fraction of the time for which the lamp is lit. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '0.5784', NULL, false, NULL, false, NULL, '(a) V₀ = 230 × √2 = 325 V. (b) sin θ = 200 ÷ 325.3 = 0.6149, so θ = sin⁻¹ 0.6149 = 37.9°. (c) It is lit from θ to 180° − θ in each half: fraction = (180 − 2 × 37.94) ÷ 180 = 0.578. Mark scheme (6 marks). C1: V₀. C1: sin⁻¹. M1: symmetric in each half. C1: fraction. B1: same for negative half. A1: fraction = 0.578.', 6),
('29cb08c0-7c66-523a-a963-d24f3e109eee', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '1dcc934a-cbaa-4233-91fd-46dc3b235528', 'a-level', '27.2', '9702 coursebook 27.2 · Alternating voltages', 44, 44, 'One cycle of a trace spans 3.5 ± 0.1 divisions with the time-base at 1.0 ms per division. (a) Calculate the frequency. (b) Calculate its percentage uncertainty. Give only the answer to (a).', NULL, 3, 'numeric'::answer_type, '285.7', 'Hz', false, NULL, false, NULL, '(a) T = 3.5 ms, so f = 1 ÷ 3.5 × 10⁻³ = 286 Hz. (b) Percentage uncertainty = 0.1 ÷ 3.5 × 100 = 2.86 %. Mark scheme (5 marks). C1: T from trace. C1: f = 1/T. C1: percentage. B1: f and T have equal percentage uncertainty. A1: f = 286 Hz.', 5),
('3c123a89-1393-5290-b6b1-207cb97cffee', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '1dcc934a-cbaa-4233-91fd-46dc3b235528', 'a-level', '27.2', '9702 coursebook 27.2 · Alternating voltages', 45, 45, 'A signal is V = 3.0 + 4.0 sin ωt, in volts: a steady 3.0 V plus a sinusoidal part of peak 4.0 V. (a) State the maximum and minimum values of V. (b) Use V_rms² = (d.c. part)² + (sinusoidal peak)²/2 to calculate the r.m.s. value. (c) Calculate the mean power it delivers to a 17 Ω resistor. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '4.123', 'V', false, NULL, false, NULL, '(a) Maximum 7.0 V, minimum −1.0 V. (b) V_rms² = 3.0² + 4.0² ÷ 2 = 17 V², so V_rms = √17 = 4.12 V. (c) P = 17 ÷ 17 = 1.0 W. Mark scheme (6 marks). C1: max and min. C1: V_rms². C1: square root. C1: P = V_rms²/R. B1: d.c. and a.c. parts add in quadrature. A1: V_rms = 4.12 V.', 6),
('ba3b7ebe-8dcb-505b-886d-169d0d074e85', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '1dcc934a-cbaa-4233-91fd-46dc3b235528', 'a-level', '27.2', '9702 coursebook 27.2 · Alternating voltages', 46, 46, 'A generator''s e.m.f. is E = 7.85 sin(157t), in volts. (a) Calculate its frequency. (b) Calculate the e.m.f. at t = 4.0 ms. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '4.612', 'V', false, NULL, false, NULL, '(a) f = 157 ÷ 2π = 25.0 Hz. (b) ωt = 157 × 4.0 × 10⁻³ = 0.628 rad, which is 36.0°: E = 7.85 × sin 36.0° = 4.61 V. Mark scheme (5 marks). C1: f = ω/2π. C1: ωt. M1: in degrees. C1: value. A1: E = 4.61 V.', 5),
('7f29acc8-bef4-5856-a53a-ac8f731bb752', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '1dcc934a-cbaa-4233-91fd-46dc3b235528', 'a-level', '27.2', '9702 coursebook 27.2 · Alternating voltages', 47, 47, 'A 10 Ω and a 30 Ω resistor in series are connected to a 12 V r.m.s. sinusoidal supply. An oscilloscope is connected across the 30 Ω resistor. (a) Calculate the r.m.s. p.d. across the 30 Ω resistor. (b) Calculate the peak p.d. across it. (c) Calculate the peak-to-peak p.d. shown on the oscilloscope. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '25.46', 'V', false, NULL, false, NULL, '(a) V = 12 × 30 ÷ 40 = 9.0 V. (b) V₀ = 9.0 × √2 = 12.7 V. (c) V_pp = 2 × 12.73 = 25.5 V. Mark scheme (6 marks). C1: potential divider. C1: × √2. C1: × 2. B1: r.m.s. values divide like d.c. C1: value. A1: V_pp = 25.5 V.', 6),
('88bdb6c1-2a62-5e30-9339-2770d646b773', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '1dcc934a-cbaa-4233-91fd-46dc3b235528', 'a-level', '27.2', '9702 coursebook 27.2 · Alternating voltages', 48, 48, 'Aircraft electrical systems use a 400 Hz supply. (a) Calculate the period. (b) Calculate the time taken for the voltage to rise from zero to its peak, in ms. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '0.625 ms', 'ms', false, NULL, false, NULL, '(a) T = 1 ÷ 400 = 2.5 × 10⁻³ s. (b) Zero to peak is a quarter cycle: 2.5 × 10⁻³ ÷ 4 = 6.25 × 10⁻⁴ s. In ms: 6.25 × 10⁻⁴ × 1000 = 0.625. Mark scheme (5 marks). C1: T = 1/f. B1: quarter of a cycle. C1: value. C1: conversion. A1: t = 0.625 ms.', 5),
('a35c84d3-af17-5358-b56a-f951d3919d4e', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '1dcc934a-cbaa-4233-91fd-46dc3b235528', 'a-level', '27.2', '9702 coursebook 27.2 · Alternating voltages', 49, 49, 'Two sinusoidal supplies of the same frequency, each of peak 10 V, are connected in series. (a) State the peak of their sum when they are in phase. (b) State it when they are 180° out of phase. (c) For a 90° phase difference, the peak of the sum is √(10² + 10²). Calculate it. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '14.14', 'V', false, NULL, false, NULL, '(a) 20 V. (b) Zero: they cancel at every instant. (c) √(10² + 10²) = 14.1 V. Mark scheme (6 marks). B1: in phase add. B1: antiphase cancel. C1: substitution. C1: value. M1: peaks not simultaneous for 90°. A1: V₀ = 14.1 V.', 6),
('6c214419-713e-537e-8c41-eb68f8441f05', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '1dcc934a-cbaa-4233-91fd-46dc3b235528', 'a-level', '27.2', '9702 coursebook 27.2 · Alternating voltages', 50, 50, 'The 230 V r.m.s. mains is displayed on an oscilloscope through a probe that divides the voltage by 10, with the Y-gain at 10 V per division. (a) Calculate the peak-to-peak mains voltage. (b) Calculate the peak-to-peak height of the trace in divisions. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '6.505', NULL, false, NULL, false, NULL, '(a) V_pp = 2 × 230 × √2 = 651 V. (b) After the probe: 650.5 ÷ 10 = 65.1 V, so height = 65.05 ÷ 10 = 6.51 divisions. Mark scheme (5 marks). C1: V_pp. C1: ÷ probe factor. C1: ÷ Y-gain. B1: fits on screen. A1: divisions = 6.51.', 5)
