('e4a37e18-b5a3-5228-a7d1-f494295b8e8b', '6d2c3852-0a62-5f2a-b402-d82b0c5ef470', 'Twice as many cycles appear across the screen', 'C', true, 2),
('e64d0003-9137-5de3-b9e6-e420695f859f', '6d2c3852-0a62-5f2a-b402-d82b0c5ef470', 'The trace does not change', 'D', false, 3),
('2323d466-8db9-565d-86c0-2530dae4e845', 'd155b2e3-8421-5505-aac6-79a1e0e51b7e', 'It becomes taller', 'A', true, 0),
