('ed17ae27-1085-5416-a181-7121f81a8334', 'd155b2e3-8421-5505-aac6-79a1e0e51b7e', 'It becomes wider', 'C', false, 2),
('33651f5c-a2e1-5117-8b93-64edfc84dc0f', 'd155b2e3-8421-5505-aac6-79a1e0e51b7e', 'It does not change', 'D', false, 3),
('08de7b31-8629-554f-b8b9-413e9438d122', '0f503757-f1b5-592a-88c9-111bcafccb0c', 'The positive half is always larger', 'A', false, 0),
('c1b30ee7-b3dc-5c0a-8ec4-b083ac61234c', '0f503757-f1b5-592a-88c9-111bcafccb0c', 'It is zero for half of each cycle', 'B', false, 1),
('b3e5a21c-0f38-5fcd-8963-148d901a9c62', '0f503757-f1b5-592a-88c9-111bcafccb0c', 'Its mean value is V₀/√2', 'C', false, 2),
('6ec9e1c8-c44c-5191-b4d6-e557c6d022db', '0f503757-f1b5-592a-88c9-111bcafccb0c', 'The positive and negative half cycles have the same shape and size', 'D', true, 3),
('a466dd17-cd60-5e93-89c6-3397044f28c8', '5810ca41-104e-5861-bc4a-6a1f8ab63746', '45°', 'A', false, 0),
