('ea4ccead-8359-5506-8136-9ffcccdd27f8', '7e0b5a54-01ee-53f1-a05c-0d8571300462', 'A single dot at the centre', 'C', false, 2),
('b3458c9e-c84b-51c5-bef8-78313b0a94be', '7e0b5a54-01ee-53f1-a05c-0d8571300462', 'A sine wave', 'D', false, 3)
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points) VALUES
('2f6c974e-4c7c-53cb-8320-c9dbc64b52ef', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 7, 7, 'A lamp on a 120 V r.m.s. supply carries an r.m.s. current of 0.50 A. Calculate its mean power.', NULL, 1, 'numeric'::answer_type, '60', 'W', false, NULL, false, NULL, 'P = V_rms I_rms = 120 × 0.50 = 60 W. Mark scheme (2 marks). C1: P = V_rms I_rms. A1: P = 60 W.', 2),
('a470bb24-26ca-503a-af48-ed803041b14b', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 8, 8, 'For a resistor on a sinusoidal supply, how is the mean power related to the peak power?', NULL, 1, 'multiple_choice'::answer_type, 'Mean power = ½ × peak power', NULL, false, NULL, false, NULL, 'P = P₀ sin² ωt has a mean of P₀/2. Mark scheme (1 mark). B1: C (Mean power = ½ × peak power).', 1),
('7a2fe1ad-59ee-53fc-acc8-7c0d2b927053', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 9, 9, 'A resistor dissipates a mean power of 100 W on a sinusoidal supply. What is the peak power?', NULL, 1, 'numeric'::answer_type, '200', 'W', false, NULL, false, NULL, 'P₀ = 2 × 100 = 200 W. Mark scheme (2 marks). C1: peak = 2 × mean. A1: P₀ = 200 W.', 2),
('a8b30a0f-be0a-5891-b487-76dbf1291cd4', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 10, 10, 'A 60 W lamp runs on a 230 V r.m.s. supply. Calculate the r.m.s. current.', NULL, 1, 'numeric'::answer_type, '0.2609', 'A', false, NULL, false, NULL, 'I = P/V = 60 ÷ 230 = 0.261 A. Mark scheme (2 marks). C1: I = P/V. A1: I = 0.261 A.', 2),
('31f960c8-6eac-5297-8016-e80efec498d5', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 11, 11, 'Which expression gives the mean power in a resistor R on a supply of r.m.s. voltage V_rms?', NULL, 1, 'multiple_choice'::answer_type, 'V_rms²/R', NULL, false, NULL, false, NULL, 'Using r.m.s. values, a.c. power formulas look like d.c. ones. Mark scheme (1 mark). B1: A (V_rms²/R).', 1),
('aada65b1-2bbf-5796-b2d7-8bbfb53f6968', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 12, 12, 'A 2.0 kW heater runs on a 230 V r.m.s. supply. Calculate its resistance.', NULL, 1, 'numeric'::answer_type, '26.45', 'Ω', false, NULL, false, NULL, 'R = V²/P = 230² ÷ 2000 = 26.4 Ω. Mark scheme (2 marks). C1: R = V_rms²/P. A1: R = 26.4 Ω.', 2),
('65d870bf-b4b7-546a-be73-6c17f827d132', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 13, 13, 'Can the instantaneous power dissipated in a resistor on an a.c. supply be negative?', NULL, 1, 'multiple_choice'::answer_type, 'No: P = I²R is never negative', NULL, false, NULL, false, NULL, 'Energy is always transferred to the resistor. Mark scheme (1 mark). B1: D (No: P = I²R is never negative).', 1),
('038b2d82-39c0-5308-9fa8-8d5bd24dd970', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 14, 14, 'A 2.0 kW heater runs for 1.5 hours. Calculate the energy used, in kW h.', NULL, 1, 'numeric'::answer_type, '3', 'kW h', false, NULL, false, NULL, 'E = Pt in kW and hours: 2.0 × 1.5 = 3.0 kW h. Mark scheme (2 marks). C1: E = Pt in kW and h. A1: E = 3.0 kW h.', 2),
('74af1784-8223-502e-846d-ca03d9d7299f', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 15, 15, 'Why are mains voltages and currents usually quoted as r.m.s. values?', NULL, 1, 'multiple_choice'::answer_type, 'Because r.m.s. values give the same heating effect as equal d.c. values, so power calculations are simple', NULL, false, NULL, false, NULL, 'P = V_rms I_rms, just like P = VI for d.c. Mark scheme (1 mark). B1: B (Because r.m.s. values give the same heating effect as equal d.c. values, so power calculations are simple).', 1),
('7ec364eb-d69e-5713-bb8c-49124ee54436', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 16, 16, 'A sinusoidal current of peak 4.0 A flows in a 5.0 Ω resistor. Calculate the mean power.', NULL, 1, 'numeric'::answer_type, '40', 'W', false, NULL, false, NULL, 'P = ½I₀²R = 0.5 × 4.0² × 5.0 = 40 W. Mark scheme (2 marks). C1: ½I₀²R. A1: P = 40 W.', 2),
('90d56171-ac0c-56eb-83f7-632208ce47a2', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 17, 17, 'The r.m.s. voltage across a resistor is doubled. What happens to the mean power?', NULL, 1, 'multiple_choice'::answer_type, 'It quadruples', NULL, false, NULL, false, NULL, 'P = V_rms²/R, so doubling V_rms makes the power four times larger. Mark scheme (1 mark). B1: C (It quadruples).', 1),
('278b369c-910e-5c31-a87c-1d291106b04b', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 18, 18, 'How many joules does a 500 W food mixer use in a 10-minute run?', NULL, 1, 'numeric'::answer_type, '3e5', 'J', false, NULL, false, NULL, 'E = Pt = 500 × 600 = 3.0 × 10⁵ J. Mark scheme (2 marks). C1: t in seconds. A1: E = 3.0 × 10⁵ J.', 2),
('6445c049-0943-5f12-98d0-e0106e9bfb6d', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 19, 19, 'What is the peak power dissipated in a resistor carrying a sinusoidal current of peak I₀ at peak voltage V₀?', NULL, 1, 'multiple_choice'::answer_type, 'V₀I₀', NULL, false, NULL, false, NULL, 'At the peak of the cycle, P = V₀I₀. Mark scheme (1 mark). B1: A (V₀I₀).', 1),
('818a235f-873b-5e36-903e-3f16f445ba92', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 20, 20, 'A resistor is moved from a 115 V r.m.s. supply to a 230 V r.m.s. supply. By what factor does its mean power increase?', NULL, 1, 'numeric'::answer_type, '4', NULL, false, NULL, false, NULL, 'P ∝ V²: (230 ÷ 115)² = 4.0. Mark scheme (1 mark). A1: factor = 4.0.', 1),
('d0814805-6273-5889-8993-8c05687e704d', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 21, 21, 'A fuse is chosen for an appliance on an a.c. supply. Which current is used to choose it?', NULL, 1, 'multiple_choice'::answer_type, 'The r.m.s. current', NULL, false, NULL, false, NULL, 'A fuse melts because of heating, which depends on I_rms. Mark scheme (1 mark). B1: D (The r.m.s. current).', 1),
('204cd0ec-529d-5f6e-8b4a-1a038283bf91', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 22, 22, 'Calculate the r.m.s. voltage needed to give a mean power of 100 W in a 25 Ω resistor.', NULL, 1, 'numeric'::answer_type, '50', 'V', false, NULL, false, NULL, 'V_rms = √(PR) = √(100 × 25) = 50 V. Mark scheme (2 marks). C1: rearranged. A1: V_rms = 50 V.', 2),
('7edf0532-c8f9-5c20-a810-d576592cd1cb', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 23, 23, 'For a resistor on a 50 Hz sinusoidal supply, how does the instantaneous power vary?', NULL, 1, 'multiple_choice'::answer_type, 'It rises and falls between zero and a maximum 100 times each second', NULL, false, NULL, false, NULL, 'P ∝ sin² ωt, which has twice the supply frequency. Mark scheme (1 mark). B1: B (It rises and falls between zero and a maximum 100 times each second).', 1),
('6c125fda-ef5d-5659-b74c-66357f86392c', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 24, 24, 'A 3.0 kW kettle runs on a 230 V r.m.s. supply. Calculate the peak current.', NULL, 2, 'numeric'::answer_type, '18.45', 'A', false, NULL, false, NULL, 'I_rms = 3000 ÷ 230 = 13.0 A. I₀ = √2 × 13.04 = 18.4 A. Mark scheme (3 marks). C1: I_rms = P/V. C1: × √2. A1: I₀ = 18.4 A.', 3),
('804fb39d-e641-541a-97e3-94aa6f9ae2b5', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 25, 25, 'A 2.5 kW oven is used for 3.0 hours. Calculate the energy used, in kW h.', NULL, 2, 'numeric'::answer_type, '7.5', 'kW h', false, NULL, false, NULL, 'E = Pt = 2.5 × 3.0 = 7.5 kW h. Mark scheme (3 marks). C1: kW × h. C1: value. A1: E = 7.5 kW h.', 3),
('d181bb3c-7fb3-5582-9067-60bb880efe79', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 26, 26, 'A resistor is connected to a 50 Hz sinusoidal supply. Calculate the frequency at which the instantaneous power oscillates.', NULL, 2, 'numeric'::answer_type, '100', 'Hz', false, NULL, false, NULL, 'P ∝ sin² ωt = ½(1 − cos 2ωt): frequency = 2 × 50 = 100 Hz. Mark scheme (3 marks). M1: sin² doubles frequency. C1: value. A1: f = 100 Hz.', 3),
('87c4778f-930b-57d9-9723-7f681e24a1df', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 27, 27, 'A 12 V, 24 W lamp (rated for 12 V d.c.) is connected to a sinusoidal supply of peak 12 V. Assuming its resistance is constant, calculate its mean power.', NULL, 2, 'numeric'::answer_type, '12', 'W', false, NULL, false, NULL, 'R = 12² ÷ 24 = 6.0 Ω. V_rms = 12 ÷ √2, so P = (12 ÷ √2)² ÷ 6.0 = 72 ÷ 6.0 = 12 W. Mark scheme (4 marks). C1: R from rating. C1: V_rms. C1: P = V_rms²/R. A1: P = 12 W.', 4),
('cf943491-7249-535e-8629-34160917d648', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 28, 28, 'A resistive load has a peak voltage of 340 V across it and a peak current of 1.5 A. Calculate the mean power.', NULL, 2, 'numeric'::answer_type, '255', 'W', false, NULL, false, NULL, 'P = ½V₀I₀ = 0.5 × 340 × 1.5 = 255 W. Mark scheme (3 marks). C1: ½V₀I₀. C1: value. A1: P = 255 W.', 3),
('76dc6bd6-18cc-5054-abfe-8ecae996a2c4', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 29, 29, 'A resistor is connected first to a 6.0 V d.c. supply and then to a 6.0 V r.m.s. a.c. supply. How do the mean powers compare?', NULL, 2, 'multiple_choice'::answer_type, 'They are equal', NULL, false, NULL, false, NULL, 'By definition, the r.m.s. value gives the same heating as the equal d.c. value. Mark scheme (3 marks). C1: definition of r.m.s. C1: equal power. A1: C (They are equal).', 3),
('0ab96a26-5aaa-58ac-9396-5b6c5f3a5086', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 30, 30, 'On a 115 V r.m.s. supply, what r.m.s. current does a 690 W microwave oven draw?', NULL, 2, 'numeric'::answer_type, '6', 'A', false, NULL, false, NULL, 'I = P/V = 690 ÷ 115 = 6.0 A. Mark scheme (3 marks). C1: I = P/V. C1: value. A1: I = 6.0 A.', 3),
('d15e4c1a-8858-5622-9ca8-d58ee47bfbd9', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 31, 31, 'A lamp takes a mean power of 60 W from a 50 Hz supply. Calculate the energy it receives during one cycle.', NULL, 2, 'numeric'::answer_type, '1.2', 'J', false, NULL, false, NULL, 'E = P × T = 60 × (1 ÷ 50) = 1.2 J. Mark scheme (4 marks). C1: T = 1/f. M1: E = P_mean × T. C1: value. A1: E = 1.2 J.', 4),
('d9893fd9-0d9d-5247-8fd7-da57dc9b1939', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 32, 32, 'Both the r.m.s. voltage across a resistor and its resistance are doubled. What happens to the mean power?', NULL, 2, 'multiple_choice'::answer_type, 'It doubles', NULL, false, NULL, false, NULL, 'P = V²/R: (2²)/2 = 2. Mark scheme (3 marks). C1: P = V²/R. C1: factor 4 ÷ 2. A1: A (It doubles).', 3),
('46792295-3a6e-5e06-b99a-acb68d33fdf1', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 33, 33, 'A resistor has a peak p.d. of 17 V across it and a peak current of 0.50 A. Calculate its resistance.', NULL, 2, 'numeric'::answer_type, '34', 'Ω', false, NULL, false, NULL, 'R = V₀/I₀ = 17 ÷ 0.50 = 34 Ω. Mark scheme (3 marks). C1: R = V/I with peak or r.m.s. values. C1: value. A1: R = 34 Ω.', 3),
('19ce5895-e39b-5d07-b9ed-2d7575eb36fa', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 34, 34, 'A 40 Ω heater and a 6.0 Ω cable resistance are in series on a 230 V r.m.s. supply. Calculate the mean power in the heater.', NULL, 2, 'numeric'::answer_type, '1000', 'W', false, NULL, false, NULL, 'I = 230 ÷ (40 + 6.0) = 5.0 A. P = I²R = 5.0² × 40 = 1000 W. Mark scheme (3 marks). C1: series current. C1: P = I²R. A1: P = 1000 W.', 3),
('b53be78b-81fa-5b17-83dc-b671dacfcb94', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 35, 35, 'Why are cables rated by their maximum r.m.s. current?', NULL, 2, 'multiple_choice'::answer_type, 'The heating of the cable depends on the mean of I², which is I_rms²', NULL, false, NULL, false, NULL, 'Overheating damages insulation; P = I_rms²R. Mark scheme (4 marks). C1: heating ∝ I². C1: mean of I² = I_rms². C1: insulation limit. A1: D (The heating of the cable depends on the mean of I², which is I_rms²).', 4),
('15572418-7dce-5a23-b13b-1c2a98490161', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 36, 36, 'A 9.0 kW electric shower runs for 8.0 minutes. Calculate the energy used, in MJ.', NULL, 2, 'numeric'::answer_type, '4.32 MJ', 'MJ', false, NULL, false, NULL, 'E = 9.0 × 10³ × 480 = 4.32 × 10⁶ J. In MJ: 4.32 × 10⁶ ÷ 10⁶ = 4.32. Mark scheme (3 marks). C1: t in s. C1: conversion. A1: E = 4.32 MJ.', 3),
('fcb0e1bd-79cd-5cb9-9572-0249ff82da88', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 37, 37, 'An appliance takes a mean power of 2.3 kW from a sinusoidal supply. Calculate the peak power, in kW.', NULL, 2, 'numeric'::answer_type, '4.6 kW', 'kW', false, NULL, false, NULL, 'P₀ = 2 × P_mean = 2 × 2.3 = 4.6 kW. Mark scheme (4 marks). M1: P₀ = I₀V₀ = 2I_rmsV_rms. C1: factor 2. C1: value. A1: P₀ = 4.6 kW.', 4),
('f9756b49-e3a2-5170-8620-00c736f06893', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 38, 38, 'How many joules are there in 1 kW h?', NULL, 2, 'multiple_choice'::answer_type, '3.6 × 10⁶ J', NULL, false, NULL, false, NULL, '1 kW h = 1000 W × 3600 s. Mark scheme (3 marks). C1: kW to W. C1: h to s. A1: B (3.6 × 10⁶ J).', 3),
('ee629949-c5be-51ad-ab2a-3a1720c336d2', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 39, 39, 'A 60 W lamp runs on a 230 V r.m.s. supply. Calculate the largest instantaneous current in it.', NULL, 2, 'numeric'::answer_type, '0.3689', 'A', false, NULL, false, NULL, 'I_rms = 60 ÷ 230 = 0.261 A. I₀ = √2 × 0.2609 = 0.369 A. Mark scheme (3 marks). C1: I_rms. C1: × √2. A1: I₀ = 0.369 A.', 3),
('271b160f-e259-540d-a7e5-72cca171e8b4', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 40, 40, 'A heater gives 1.2 kW on a 230 V r.m.s. supply. Calculate its power, in W, when the supply falls to 207 V r.m.s., assuming constant resistance.', NULL, 2, 'numeric'::answer_type, '972', 'W', false, NULL, false, NULL, 'P ∝ V²: P = 1200 × (207 ÷ 230)² = 972 W. Mark scheme (3 marks). C1: P ∝ V². C1: value. A1: P = 972 W.', 3),
('28fabbaf-02f7-572d-a91b-fdf9d40de7c9', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 41, 41, 'A 3.0 kW heater runs on a 230 V r.m.s. supply. (a) Calculate the r.m.s. current. (b) Calculate the resistance. (c) Calculate the peak current and the peak power. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '17.63', 'Ω', false, NULL, false, NULL, '(a) I_rms = 3000 ÷ 230 = 13.0 A. (b) R = V²/P = 230² ÷ 3000 = 17.6 Ω. (c) I₀ = √2 × 13.04 = 18.4 A; P₀ = 2 × 3.0 = 6.0 kW. Mark scheme (5 marks). C1: I_rms. C1: R. C1: I₀. C1: P₀ = 2P. A1: R = 17.6 Ω.', 5),
('738722dc-5dfb-5846-8bc1-1c44960ef294', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 42, 42, 'A current of 5.0 A flows through a 20 Ω resistor for 0.30 of each cycle and is zero for the rest. (a) Calculate the mean power. (b) Calculate the r.m.s. current. Give only the answer to (a).', NULL, 3, 'numeric'::answer_type, '150', 'W', false, NULL, false, NULL, '(a) While on, P = 5.0² × 20 = 500 W; mean = 0.30 × 500 = 150 W. (b) I_rms = √(0.30 × 5.0²) = 2.74 A; check I_rms² × 20 = 150 W. Mark scheme (5 marks). C1: power while on. M1: × fraction of time. C1: value. C1: I_rms. A1: P = 150 W.', 5),
('1bc25881-c298-52fa-bf6a-d4a93d857cb6', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 43, 43, 'An electric shower draws 40 A r.m.s. from a 230 V r.m.s. supply. The cable has a total resistance of 0.10 Ω. (a) Calculate the power drawn from the supply. (b) Calculate the power wasted in the cable. (c) Calculate this as a percentage of the supply power. (d) Suggest why thick cables are used for showers. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '160', 'W', false, NULL, false, NULL, '(a) P = 230 × 40 = 9200 W. (b) P_cable = 40² × 0.10 = 160 W. (c) 160 ÷ 9200 × 100 = 1.74 %. (d) Thick cables have low resistance, so less heating at large currents. Mark scheme (6 marks). C1: P = VI. C1: I²R. C1: percentage. B1: low resistance. C1: value. A1: P = 160 W.', 6),
('6edd8592-d4b6-5690-9012-7c6080428ca5', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 44, 44, 'A 150 W refrigerator runs for 40 % of the time. (a) Calculate the energy it uses in one day, in kW h. (b) Calculate this in MJ. Give only the answer to (a).', NULL, 3, 'numeric'::answer_type, '1.44', 'kW h', false, NULL, false, NULL, '(a) In kW and hours: E = 0.150 × 24 × 0.40 = 1.44 kW h. (b) 1.440 × 3.6 = 5.18 MJ. Mark scheme (5 marks). C1: W to kW. C1: × 24 h × 0.40. C1: value. B1: 1 kW h = 3.6 MJ. A1: E = 1.44 kW h.', 5),
('b1f2cdbb-2158-5cc6-a9e3-7e3118579a82', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 45, 45, 'A 40 Ω lamp is supplied through a single diode from a 230 V r.m.s. mains supply, so it receives only half of each cycle. (a) Calculate the mean power it would take with no diode. (b) Calculate the mean power with the diode. (c) Explain why the lamp flickers at 50 Hz. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '661.2', 'W', false, NULL, false, NULL, '(a) P = 230² ÷ 40 = 1320 W. (b) Only half the cycles deliver energy: P = 1322 ÷ 2 = 661 W. (c) It receives one pulse of power per cycle, 50 per second. Mark scheme (6 marks). C1: full-wave power. M1: half the energy. C1: value. B1: one pulse per cycle. B1: flicker at 50 Hz. A1: P = 661 W.', 6),
('bfe50aca-1fef-5ed4-91e9-6d4b16d9a658', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 46, 46, 'A sinusoidal voltage and a square-wave voltage have the same peak value V₀ and are applied in turn to the same resistor. (a) State the r.m.s. value of each. (b) Calculate (mean power with square wave) ÷ (mean power with sine wave). Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '2', NULL, false, NULL, false, NULL, '(a) Square wave: V₀. Sine wave: V₀/√2. (b) P ∝ V_rms²: ratio = V₀² ÷ (V₀²/2) = 2 × 1 = 2.0. Mark scheme (5 marks). C1: square r.m.s. C1: sine r.m.s. M1: P ∝ V_rms². C1: ratio. A1: ratio = 2.0.', 5),
('ccea4d23-287c-5a8d-acbc-30b8f4558b06', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 47, 47, 'The instantaneous power in a resistor on a sinusoidal supply is P = P₀ sin² ωt, with P₀ = 2.0 kW. (a) State the mean power. (b) Calculate the instantaneous power at t = T/6. (c) Explain why P is never negative. Give only the answer to (b), in kW.', NULL, 3, 'numeric'::answer_type, '1.5 kW', 'kW', false, NULL, false, NULL, '(a) P₀/2 = 1.0 kW. (b) At t = T/6, ωt = 60°: P = 2.0 × sin² 60° = 2.0 × 0.750 = 1.50 kW. (c) sin² is never negative, because P = I²R. Mark scheme (6 marks). C1: mean P₀/2. M1: ωt = 60°. C1: sin² 60°. C1: value. B1: I² ≥ 0. A1: P = 1.50 kW.', 6),
('293d46e9-1cf4-5e54-8dca-a2f279d32ebe', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 48, 48, 'Heaters rated 1.0 kW and 2.0 kW (each at 230 V r.m.s.) are connected in series to a 230 V r.m.s. supply. (a) Calculate the resistance of each. (b) Calculate the current. (c) Calculate the power in the 1.0 kW heater. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '444.4', 'W', false, NULL, false, NULL, '(a) R₁ = 230² ÷ 1000 = 52.9 Ω; R₂ = 230² ÷ 2000 = 26.4 Ω. (b) I = 230 ÷ (52.90 + 26.45) = 2.90 A. (c) P = (2.899)² × 52.90 = 444 W. Mark scheme (5 marks). C1: resistances. C1: series current. C1: P = I²R. B1: less than rated power. A1: P = 444 W.', 5),
('569229d0-25a6-598d-819e-70da7d7c0f6e', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 49, 49, 'A transmission line operates at 400 kV r.m.s. (a) Calculate the peak voltage, in kV. (b) Calculate the peak-to-peak voltage. (c) Explain why the insulators must be designed for the peak, not the r.m.s., value. Give only the answer to (a).', NULL, 3, 'numeric'::answer_type, '565.7 kV', 'kV', false, NULL, false, NULL, '(a) V₀ = 400 × √2 = 566 kV. (b) V_pp = 2 × 565.7 = 1130 kV. (c) Breakdown happens at the largest instantaneous voltage. Mark scheme (5 marks). C1: × √2. C1: value. C1: × 2. B1: breakdown at peak. A1: V₀ = 566 kV.', 5),
('c7d83b4a-25ab-54b6-8306-49432b59927a', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '53ce2bac-1ccd-4752-8293-357079212398', 'a-level', '27.3', '9702 coursebook 27.3 · Power and alternating current', 50, 50, 'A sinusoidal current of peak 2.0 A flows through a 50 Ω resistor for 10 minutes. (a) Calculate the mean power. (b) Calculate the energy dissipated. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '60000', 'J', false, NULL, false, NULL, '(a) P = ½ × 2.0² × 50 = 100 W. (b) E = 100 × 600 = 6.0 × 10⁴ J. Mark scheme (5 marks). C1: ½I₀²R. C1: value. C1: t in s. C1: E = Pt. A1: E = 6.0 × 10⁴ J.', 5)
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES
('8e5be8b8-018f-53fe-a5a0-bfe691d11dfb', 'a470bb24-26ca-503a-af48-ed803041b14b', 'Mean power = peak power', 'A', false, 0),
('a17e9bdd-19a1-5fd8-b4a1-bfe5af6a8d1b', 'a470bb24-26ca-503a-af48-ed803041b14b', 'Mean power = 2 × peak power', 'B', false, 1),
('23c7257e-bf63-5d79-b2ea-07b286854d44', 'a470bb24-26ca-503a-af48-ed803041b14b', 'Mean power = ½ × peak power', 'C', true, 2),
('f66088d4-99b9-5f0a-823b-e00856e4ea5c', 'a470bb24-26ca-503a-af48-ed803041b14b', 'Mean power = peak power ÷ √2', 'D', false, 3),
('2818d8f7-dad8-5a0b-b7ae-04493e39226a', '31f960c8-6eac-5297-8016-e80efec498d5', 'V_rms²/R', 'A', true, 0),
('70004084-0f04-5471-b075-32b42f8d5d9a', '31f960c8-6eac-5297-8016-e80efec498d5', 'V₀²/R', 'B', false, 1),
('320ffa6a-4a0d-5271-b667-72a1960fc085', '31f960c8-6eac-5297-8016-e80efec498d5', 'V_rms/R', 'C', false, 2),
('805b7076-780a-5f08-81f8-fc70a2f92d86', '31f960c8-6eac-5297-8016-e80efec498d5', 'V_rms²R', 'D', false, 3),
('983b9a39-9bda-5c28-9224-6faba6789a4a', '65d870bf-b4b7-546a-be73-6c17f827d132', 'Yes, during the negative half cycle', 'A', false, 0),
('acae83cf-1078-5450-a6b9-ace98c95bb59', '65d870bf-b4b7-546a-be73-6c17f827d132', 'Yes, at the peak of each cycle', 'B', false, 1),
('eaf77919-0fa0-5fec-beb6-6457e9f9919d', '65d870bf-b4b7-546a-be73-6c17f827d132', 'Only when the frequency is high', 'C', false, 2),
('b3cbaea4-d6e9-5de2-8336-d3e35c1de6ff', '65d870bf-b4b7-546a-be73-6c17f827d132', 'No: P = I²R is never negative', 'D', true, 3),
('280d60b8-f0fd-584c-96b8-48ba861a80b9', '74af1784-8223-502e-846d-ca03d9d7299f', 'Because they are the largest values', 'A', false, 0),
('03834e25-399a-58fe-95ca-2ed25309ccc8', '74af1784-8223-502e-846d-ca03d9d7299f', 'Because r.m.s. values give the same heating effect as equal d.c. values, so power calculations are simple', 'B', true, 1),
('9973d988-5286-57bc-aa7c-d6ac29416bb3', '74af1784-8223-502e-846d-ca03d9d7299f', 'Because they are the peak values', 'C', false, 2),
('710c2706-fec1-52aa-b287-41564bb017d9', '74af1784-8223-502e-846d-ca03d9d7299f', 'Because the mean values are always zero', 'D', false, 3),
('43fd7ed0-bfbb-5b36-b0d4-24b13c5695f3', '90d56171-ac0c-56eb-83f7-632208ce47a2', 'It doubles', 'A', false, 0),
('bb2093c5-0829-5e3e-9fa3-c196375e5487', '90d56171-ac0c-56eb-83f7-632208ce47a2', 'It halves', 'B', false, 1),
('3b92cc54-6b4b-5e6e-831d-3f8e3620a52a', '90d56171-ac0c-56eb-83f7-632208ce47a2', 'It quadruples', 'C', true, 2),
('4fdea6a6-3235-5331-8fb8-69e5c9243c11', '90d56171-ac0c-56eb-83f7-632208ce47a2', 'It stays the same', 'D', false, 3),
('2012038f-a0e3-5df4-a914-c4e03de0d9d9', '6445c049-0943-5f12-98d0-e0106e9bfb6d', 'V₀I₀', 'A', true, 0),
('ffa4440d-b726-5cc7-ba6e-34721abde475', '6445c049-0943-5f12-98d0-e0106e9bfb6d', '½V₀I₀', 'B', false, 1),
('24524053-b746-5ae9-9df3-c6928057c16d', '6445c049-0943-5f12-98d0-e0106e9bfb6d', 'V₀I₀/√2', 'C', false, 2),
('5ca3b1ff-8530-503f-8d2f-1d62736bf715', '6445c049-0943-5f12-98d0-e0106e9bfb6d', '2V₀I₀', 'D', false, 3),
('b8b1e735-9ca2-567a-8762-f0c94e079891', 'd0814805-6273-5889-8993-8c05687e704d', 'The peak current', 'A', false, 0),
('4a9edd72-d110-5d4e-be40-fafce874a06c', 'd0814805-6273-5889-8993-8c05687e704d', 'The mean current', 'B', false, 1),
('71d71dc5-a2cf-5cd3-9498-d99c17b6483c', 'd0814805-6273-5889-8993-8c05687e704d', 'The peak-to-peak current', 'C', false, 2),
('5ddf054a-d5d3-58d9-af25-376f1e4fe9e2', 'd0814805-6273-5889-8993-8c05687e704d', 'The r.m.s. current', 'D', true, 3),
('586e804c-23b6-5da6-ae53-6f68e98b97c5', '7edf0532-c8f9-5c20-a810-d576592cd1cb', 'It is constant', 'A', false, 0),
('99fd42ba-6107-57ad-84f5-229838a56f09', '7edf0532-c8f9-5c20-a810-d576592cd1cb', 'It rises and falls between zero and a maximum 100 times each second', 'B', true, 1),
('2b9d935e-9274-5466-8e40-b933fe0e1c3e', '7edf0532-c8f9-5c20-a810-d576592cd1cb', 'It reverses direction 100 times a second', 'C', false, 2),
('1f47d04e-4f19-5bfc-aa71-8b1f3497bde3', '7edf0532-c8f9-5c20-a810-d576592cd1cb', 'It varies at 50 Hz between −P₀ and +P₀', 'D', false, 3),
('eb66606d-b876-5fd8-8bf9-e6dd2bd4a719', '76dc6bd6-18cc-5054-abfe-8ecae996a2c4', 'The d.c. power is twice the a.c. power', 'A', false, 0),
('768d76e5-b46b-5cfd-9260-ebf31d704a5f', '76dc6bd6-18cc-5054-abfe-8ecae996a2c4', 'The a.c. power is twice the d.c. power', 'B', false, 1),
('7fda071a-37ad-5c64-a219-2d1342929e7b', '76dc6bd6-18cc-5054-abfe-8ecae996a2c4', 'They are equal', 'C', true, 2),
('e5dcfcdf-f9d5-55c4-9c98-3499de45bed1', '76dc6bd6-18cc-5054-abfe-8ecae996a2c4', 'The a.c. power is √2 times the d.c. power', 'D', false, 3),
('90f93f95-f803-50d6-be3d-c403c194b91a', 'd9893fd9-0d9d-5247-8fd7-da57dc9b1939', 'It doubles', 'A', true, 0),
('8e72d1d1-57a3-548d-97ce-1dd1d0f7c98f', 'd9893fd9-0d9d-5247-8fd7-da57dc9b1939', 'It quadruples', 'B', false, 1),
('3767f4a0-a29e-589a-8ef9-b14f23557cb5', 'd9893fd9-0d9d-5247-8fd7-da57dc9b1939', 'It stays the same', 'C', false, 2),
('34021c72-1725-52f4-bc84-e3256520549e', 'd9893fd9-0d9d-5247-8fd7-da57dc9b1939', 'It halves', 'D', false, 3),
('728f9882-d025-509b-b2ee-bce111ce32e7', 'b53be78b-81fa-5b17-83dc-b671dacfcb94', 'The peak current never exceeds the r.m.s. value', 'A', false, 0),
('2e755eae-1bd1-53f1-bb25-6da4889b5814', 'b53be78b-81fa-5b17-83dc-b671dacfcb94', 'The mean current is the largest value', 'B', false, 1),
('7b43509d-5768-5624-b83e-2759b159a103', 'b53be78b-81fa-5b17-83dc-b671dacfcb94', 'Insulation only fails at the mean current', 'C', false, 2),
('553f010a-5609-5581-880f-2aa3301b56c3', 'b53be78b-81fa-5b17-83dc-b671dacfcb94', 'The heating of the cable depends on the mean of I², which is I_rms²', 'D', true, 3),
('69cb33cd-485a-56c6-8b16-95a0f7806d44', 'f9756b49-e3a2-5170-8620-00c736f06893', '1000 J', 'A', false, 0),
('b9866feb-a1f0-5e21-b69d-e19a6ebb7a75', 'f9756b49-e3a2-5170-8620-00c736f06893', '3.6 × 10⁶ J', 'B', true, 1),
('1b3a4468-494a-5d4a-9817-95cde40d79d2', 'f9756b49-e3a2-5170-8620-00c736f06893', '3600 J', 'C', false, 2),
('997da787-1e84-530e-bd6c-4cc36e2e2609', 'f9756b49-e3a2-5170-8620-00c736f06893', '3.6 × 10³ J', 'D', false, 3)
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points) VALUES
('53482893-8f88-5f75-9c70-260d2459e4e8', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '71ba01f7-9a9e-5018-974d-21999c276ce5', 'a-level', '27.4', '9702 coursebook 27.4 · Rectification and smoothing', 9, 9, 'What does the output of a half-wave rectifier look like?', NULL, 1, 'multiple_choice'::answer_type, 'Only the positive half cycles; the negative half cycles are removed', NULL, false, NULL, false, NULL, 'A single diode conducts in one direction only. Mark scheme (1 mark). B1: C (Only the positive half cycles; the negative half cycles are removed).', 1),
('285f433c-38f4-5054-9760-b2e115a7b1e3', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '71ba01f7-9a9e-5018-974d-21999c276ce5', 'a-level', '27.4', '9702 coursebook 27.4 · Rectification and smoothing', 10, 10, 'What does the output of a full-wave bridge rectifier look like?', NULL, 1, 'multiple_choice'::answer_type, 'A series of positive humps: the negative half cycles are turned positive', NULL, false, NULL, false, NULL, 'Four diodes route both halves of the cycle the same way through the load. Mark scheme (1 mark). B1: A (A series of positive humps: the negative half cycles are turned positive).', 1),
('64417728-7f67-52d0-b119-60f0e66f049f', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '71ba01f7-9a9e-5018-974d-21999c276ce5', 'a-level', '27.4', '9702 coursebook 27.4 · Rectification and smoothing', 11, 11, 'A 50 Hz supply is full-wave rectified. Calculate the time between successive peaks of the output.', NULL, 1, 'numeric'::answer_type, '0.01', 's', false, NULL, false, NULL, 'There are 2 × 50 = 100 peaks per second, so the time between peaks = 1 ÷ 100 = 0.010 s. Mark scheme (2 marks). C1: two peaks per cycle. A1: t = 0.010 s.', 2),
('cdf41919-50b4-52ac-aefc-98dd76a34d25', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '71ba01f7-9a9e-5018-974d-21999c276ce5', 'a-level', '27.4', '9702 coursebook 27.4 · Rectification and smoothing', 12, 12, 'A 1000 µF smoothing capacitor is used with a 2.2 kΩ load. Calculate the time constant.', NULL, 1, 'numeric'::answer_type, '2.2', 's', false, NULL, false, NULL, 'τ = RC = 2.2 × 10³ × 1000 × 10⁻⁶ = 2.2 s. Mark scheme (2 marks). C1: τ = RC. A1: τ = 2.2 s.', 2),
('2ff58297-fcfe-54bc-be6c-175e7232ad1b', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '71ba01f7-9a9e-5018-974d-21999c276ce5', 'a-level', '27.4', '9702 coursebook 27.4 · Rectification and smoothing', 13, 13, 'Which property of a diode is used in a rectifier?', NULL, 1, 'multiple_choice'::answer_type, 'It conducts in only one direction', NULL, false, NULL, false, NULL, 'Current can flow forwards but not backwards through the diode. Mark scheme (1 mark). B1: D (It conducts in only one direction).', 1),
('7706dce3-ed79-5ba1-908f-c78df0ab982e', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '71ba01f7-9a9e-5018-974d-21999c276ce5', 'a-level', '27.4', '9702 coursebook 27.4 · Rectification and smoothing', 14, 14, 'A transformer gives 12 V r.m.s. to a rectifier. Ignoring the diodes, calculate the peak output voltage.', NULL, 1, 'numeric'::answer_type, '16.97', 'V', false, NULL, false, NULL, 'V₀ = √2 × 12 = 17.0 V. Mark scheme (2 marks). C1: V₀ = √2 V_rms. A1: V₀ = 17.0 V.', 2),
('6eca75a2-a3c1-524b-b809-d19f9b150578', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '71ba01f7-9a9e-5018-974d-21999c276ce5', 'a-level', '27.4', '9702 coursebook 27.4 · Rectification and smoothing', 15, 15, 'A larger smoothing capacitor is used, with the same load. What happens to the ripple?', NULL, 1, 'multiple_choice'::answer_type, 'It decreases', NULL, false, NULL, false, NULL, 'A larger RC means the capacitor discharges less between peaks. Mark scheme (1 mark). B1: B (It decreases).', 1),
('a97f2533-4945-5f13-b11f-8bda872ae4d5', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '71ba01f7-9a9e-5018-974d-21999c276ce5', 'a-level', '27.4', '9702 coursebook 27.4 · Rectification and smoothing', 16, 16, 'A bridge rectifier is fed with 12 V r.m.s. Two diodes, each with a forward p.d. of 0.70 V, conduct at a time. Calculate the peak output.', NULL, 1, 'numeric'::answer_type, '15.57', 'V', false, NULL, false, NULL, 'V₀ = √2 × 12 − 2 × 0.70 = 15.6 V. Mark scheme (2 marks). C1: subtract two diode drops. A1: V₀ = 15.6 V.', 2),
('f40cf8fa-93e9-551b-b7be-5faa8a8fb656', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '71ba01f7-9a9e-5018-974d-21999c276ce5', 'a-level', '27.4', '9702 coursebook 27.4 · Rectification and smoothing', 17, 17, 'In a full-wave bridge rectifier, how many diodes conduct at any one time?', NULL, 1, 'multiple_choice'::answer_type, '2', NULL, false, NULL, false, NULL, 'Two diodes conduct during each half cycle, the other two during the next. Mark scheme (1 mark). B1: C (2).', 1),
('e1f5abde-16cb-52c9-9fe9-24910b25374c', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '71ba01f7-9a9e-5018-974d-21999c276ce5', 'a-level', '27.4', '9702 coursebook 27.4 · Rectification and smoothing', 18, 18, 'A 60 Hz supply is half-wave rectified. Calculate the frequency of the output pulses.', NULL, 1, 'numeric'::answer_type, '60', 'Hz', false, NULL, false, NULL, 'One output pulse per input cycle: pulses per second = 60 × 1 = 60, so f = 60 Hz. Mark scheme (2 marks). C1: one pulse per cycle. A1: f = 60 Hz.', 2),
('a959fa1a-9aa4-5b92-aff1-f26b9d2059da', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '71ba01f7-9a9e-5018-974d-21999c276ce5', 'a-level', '27.4', '9702 coursebook 27.4 · Rectification and smoothing', 19, 19, 'In a smoothed rectifier, when does the smoothing capacitor charge?', NULL, 1, 'multiple_choice'::answer_type, 'When the rectified voltage rises above the capacitor''s voltage', NULL, false, NULL, false, NULL, 'Between peaks the diodes are reverse-biased and the capacitor discharges through the load. Mark scheme (1 mark). B1: A (When the rectified voltage rises above the capacitor''s voltage).', 1),
('c8306818-5291-5678-b14a-ce432c2ea66f', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '71ba01f7-9a9e-5018-974d-21999c276ce5', 'a-level', '27.4', '9702 coursebook 27.4 · Rectification and smoothing', 20, 20, 'A 60 Hz supply is full-wave rectified. How many output peaks are there each second?', NULL, 1, 'numeric'::answer_type, '120', NULL, false, NULL, false, NULL, 'Two output peaks per input cycle: 2 × 60 = 120 peaks per second. Mark scheme (1 mark). A1: peaks = 120.', 1),
('a90f905e-da15-5240-a36c-d5a8f21b300f', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '71ba01f7-9a9e-5018-974d-21999c276ce5', 'a-level', '27.4', '9702 coursebook 27.4 · Rectification and smoothing', 21, 21, 'Why does a single-diode (half-wave) rectifier waste much of the supply?', NULL, 1, 'multiple_choice'::answer_type, 'It blocks the negative half of every cycle, so no energy is delivered for half the time', NULL, false, NULL, false, NULL, 'Only one half cycle in two reaches the load. Mark scheme (1 mark). B1: D (It blocks the negative half of every cycle, so no energy is delivered for half the time).', 1),
('ab63b92c-4c4b-59c3-8585-1231276d9121', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '71ba01f7-9a9e-5018-974d-21999c276ce5', 'a-level', '27.4', '9702 coursebook 27.4 · Rectification and smoothing', 22, 22, 'A 470 µF smoothing capacitor is charged to 15 V at a peak. Calculate the charge stored, in mC.', NULL, 1, 'numeric'::answer_type, '7.05 mC', 'mC', false, NULL, false, NULL, 'Q = CV = 470 × 10⁻⁶ × 15 = 0.00705 C. In mC: 0.007050 × 1000 = 7.05. Mark scheme (2 marks). C1: Q = CV. A1: Q = 7.05 mC.', 2),
('b3260d37-ddc6-550c-8517-34330e456edf', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '71ba01f7-9a9e-5018-974d-21999c276ce5', 'a-level', '27.4', '9702 coursebook 27.4 · Rectification and smoothing', 23, 23, 'What is meant by ripple in the output of a smoothed rectifier?', NULL, 1, 'multiple_choice'::answer_type, 'The small variation in output voltage that remains after smoothing', NULL, false, NULL, false, NULL, 'The capacitor discharges slightly between peaks. Mark scheme (1 mark). B1: B (The small variation in output voltage that remains after smoothing).', 1),
('156050e7-3edf-5a4d-ba19-b853623c0571', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '71ba01f7-9a9e-5018-974d-21999c276ce5', 'a-level', '27.4', '9702 coursebook 27.4 · Rectification and smoothing', 24, 24, 'A smoothing circuit needs a time constant of 0.50 s with a 500 Ω load. Calculate the capacitance needed, in µF.', NULL, 1, 'numeric'::answer_type, '1000', 'µF', false, NULL, false, ARRAY['0.001']::text[], 'C = τ/R = 0.50 ÷ 500 = 1.0 × 10⁻³ F. In µF: 1.0 × 10⁻³ × 10⁶ = 1000. Mark scheme (2 marks). C1: C = τ/R. A1: C = 1000 µF.', 2),
('1b8f62cf-bc90-5ca1-891c-c06f5d7eae61', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '71ba01f7-9a9e-5018-974d-21999c276ce5', 'a-level', '27.4', '9702 coursebook 27.4 · Rectification and smoothing', 25, 25, 'A smoothed full-wave output has a peak of 15 V. Between peaks (0.010 s) the capacitor discharges through the load with RC = 0.50 s. Using ΔV ≈ V₀t/RC, estimate the ripple.', NULL, 2, 'numeric'::answer_type, '0.3', 'V', false, NULL, false, NULL, 'ΔV ≈ 15 × 0.010 ÷ 0.50 = 0.30 V. Mark scheme (3 marks). M1: ΔV ≈ V₀t/RC. C1: value. A1: ΔV = 0.30 V.', 3),
('c632c229-6822-5a20-96be-fb6290b0359a', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '71ba01f7-9a9e-5018-974d-21999c276ce5', 'a-level', '27.4', '9702 coursebook 27.4 · Rectification and smoothing', 26, 26, 'A smoothing capacitor charged to 15 V discharges through a load with RC = 0.20 s for 10 ms between peaks. Calculate the p.d. just before the next peak.', NULL, 2, 'numeric'::answer_type, '14.27', 'V', false, NULL, false, NULL, 'V = V₀e^(−t/RC) = 15 × e^(−0.010/0.20) = 14.3 V. Mark scheme (3 marks). C1: exponential decay. C1: value. A1: V = 14.3 V.', 3),
('2994d944-e57b-5964-aa63-3f9edfb73776', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '71ba01f7-9a9e-5018-974d-21999c276ce5', 'a-level', '27.4', '9702 coursebook 27.4 · Rectification and smoothing', 27, 27, 'The load resistance across a smoothed rectifier is doubled, with the same capacitor. What happens to the ripple?', NULL, 2, 'multiple_choice'::answer_type, 'It roughly halves', NULL, false, NULL, false, NULL, 'Doubling R doubles RC, so the capacitor discharges about half as much between peaks. Mark scheme (3 marks). C1: RC doubles. C1: ΔV ∝ 1/RC. A1: C (It roughly halves).', 3),
('0a742640-ff33-5c48-aec3-486e6d285300', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '71ba01f7-9a9e-5018-974d-21999c276ce5', 'a-level', '27.4', '9702 coursebook 27.4 · Rectification and smoothing', 28, 28, 'A full-wave rectifier on a 50 Hz supply has a peak output of 12 V and feeds a 240 Ω load. Estimate the capacitance needed for a ripple of no more than 0.50 V, in µF, using ΔV ≈ It/C.', NULL, 2, 'numeric'::answer_type, '1000', 'µF', false, NULL, false, ARRAY['0.001']::text[], 'I ≈ 12 ÷ 240 = 0.050 A. C ≈ It/ΔV = 0.050 × 0.010 ÷ 0.50 = 1.0 × 10⁻³ F. In µF: 1.0 × 10⁻³ × 10⁶ = 1000. Mark scheme (4 marks). C1: load current. M1: ΔQ = It = CΔV. C1: C. A1: C = 1000 µF.', 4),
('6e7cca16-7862-5854-a10e-4727cffed00a', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '71ba01f7-9a9e-5018-974d-21999c276ce5', 'a-level', '27.4', '9702 coursebook 27.4 · Rectification and smoothing', 29, 29, 'A smoothed rectifier gives about 12 V across a 1.0 kΩ load. Calculate the load current, in mA.', NULL, 2, 'numeric'::answer_type, '12 mA', 'mA', false, NULL, false, NULL, 'I = V/R = 12 ÷ 1000 = 0.012 A. In mA: 0.012 × 1000 = 12. Mark scheme (3 marks). C1: I = V/R. C1: conversion. A1: I = 12 mA.', 3),
('3789e9b0-c897-528d-a236-a8194c382018', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '71ba01f7-9a9e-5018-974d-21999c276ce5', 'a-level', '27.4', '9702 coursebook 27.4 · Rectification and smoothing', 30, 30, 'With the same capacitor and load, how does the ripple from a full-wave rectifier compare with that from a half-wave rectifier?', NULL, 2, 'multiple_choice'::answer_type, 'It is about half as large, because the capacitor discharges for only half as long between peaks', NULL, false, NULL, false, NULL, 'Full-wave peaks come every T/2 instead of every T. Mark scheme (3 marks). C1: shorter discharge time. C1: smaller ripple. A1: A (It is about half as large, because the capacitor discharges for only half as long between peaks).', 3),
('e56b5814-8321-53bb-8ee7-3dc945e96e91', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '71ba01f7-9a9e-5018-974d-21999c276ce5', 'a-level', '27.4', '9702 coursebook 27.4 · Rectification and smoothing', 31, 31, 'A 470 µF smoothing capacitor''s p.d. falls by 0.40 V between peaks. Calculate the charge it supplies to the load in that time, in µC.', NULL, 2, 'numeric'::answer_type, '188 uC', 'µC', false, NULL, false, NULL, 'ΔQ = CΔV = 470 × 10⁻⁶ × 0.40 = 1.88 × 10⁻⁴ C. In µC: 1.88 × 10⁻⁴ × 10⁶ = 188. Mark scheme (3 marks). C1: ΔQ = CΔV. C1: conversion. A1: ΔQ = 188 µC.', 3),
('d2c3b120-c710-5401-9368-a98fa1c0c4c9', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '71ba01f7-9a9e-5018-974d-21999c276ce5', 'a-level', '27.4', '9702 coursebook 27.4 · Rectification and smoothing', 32, 32, 'A 1000 µF smoothing capacitor''s p.d. falls from 15.0 V to 14.5 V between peaks. Calculate the energy it delivers to the load, in mJ.', NULL, 2, 'numeric'::answer_type, '7.375 mJ', 'mJ', false, NULL, false, NULL, 'ΔW = ½C(V₁² − V₂²) = 0.5 × 1000 × 10⁻⁶ × (15.0² − 14.5²) = 0.00738 J. In mJ: 0.007375 × 1000 = 7.38. Mark scheme (4 marks). M1: difference of ½CV². C1: substitution. C1: conversion. A1: ΔW = 7.38 mJ.', 4),
('36b3f5d9-2114-5fe7-8665-59d42fa18e16', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '71ba01f7-9a9e-5018-974d-21999c276ce5', 'a-level', '27.4', '9702 coursebook 27.4 · Rectification and smoothing', 33, 33, 'Which change would NOT reduce the ripple from a smoothed rectifier?', NULL, 2, 'multiple_choice'::answer_type, 'Using a lower-frequency a.c. supply', NULL, false, NULL, false, NULL, 'A lower frequency means longer gaps between peaks, so more discharge. Mark scheme (4 marks). C1: larger C or R reduces ripple. C1: full-wave halves gap. C1: lower f increases gap. A1: D (Using a lower-frequency a.c. supply).', 4),
('581c8755-2f6c-5d70-9a9b-0fe3d6737afc', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '71ba01f7-9a9e-5018-974d-21999c276ce5', 'a-level', '27.4', '9702 coursebook 27.4 · Rectification and smoothing', 34, 34, 'A 9.0 V r.m.s. supply feeds a bridge rectifier whose conducting diodes each drop 0.70 V. Calculate the peak output voltage.', NULL, 2, 'numeric'::answer_type, '11.33', 'V', false, NULL, false, NULL, 'V₀ = √2 × 9.0 − 2 × 0.70 = 11.3 V. Mark scheme (3 marks). C1: V₀ = √2 V_rms. C1: two diode drops. A1: V₀ = 11.3 V.', 3),
('c506e6b3-6a83-521d-a9b6-93f8a14147de', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '71ba01f7-9a9e-5018-974d-21999c276ce5', 'a-level', '27.4', '9702 coursebook 27.4 · Rectification and smoothing', 35, 35, 'A smoothing circuit has RC = 0.47 s and is fed by a full-wave rectifier on a 50 Hz supply. Calculate (time constant) ÷ (time between peaks).', NULL, 2, 'numeric'::answer_type, '47', NULL, false, NULL, false, NULL, 'Time between peaks = 1 ÷ 100 = 0.010 s. Ratio = 0.47 ÷ 0.010 = 47. Mark scheme (3 marks). C1: time between peaks. C1: ratio. A1: ratio = 47.', 3),
('071b29e1-c954-5d22-9d03-8bddb284f6e1', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '71ba01f7-9a9e-5018-974d-21999c276ce5', 'a-level', '27.4', '9702 coursebook 27.4 · Rectification and smoothing', 36, 36, 'One diode in a bridge rectifier fails, becoming an open circuit. What happens to the output?', NULL, 2, 'multiple_choice'::answer_type, 'It becomes half-wave rectified', NULL, false, NULL, false, NULL, 'Only the path through the working pair of diodes remains for one half cycle. Mark scheme (3 marks). C1: one current path lost. C1: half-wave output. A1: B (It becomes half-wave rectified).', 3),
('6a04c172-7fe6-5718-b100-500f714713af', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '71ba01f7-9a9e-5018-974d-21999c276ce5', 'a-level', '27.4', '9702 coursebook 27.4 · Rectification and smoothing', 37, 37, 'For a smoothed full-wave rectifier on 50 Hz, the ripple must be about 2.0 % of the peak voltage. Using ΔV/V₀ ≈ t/RC, calculate the time constant needed.', NULL, 2, 'numeric'::answer_type, '0.5', 's', false, NULL, false, NULL, 'RC = t ÷ (ΔV/V₀) = 0.010 ÷ 0.020 = 0.50 s. Mark scheme (3 marks). C1: t = 0.010 s. C1: rearranged. A1: RC = 0.50 s.', 3),
('1ce10728-3de2-5866-a25c-cd045cf790fa', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '71ba01f7-9a9e-5018-974d-21999c276ce5', 'a-level', '27.4', '9702 coursebook 27.4 · Rectification and smoothing', 38, 38, 'A smoothing capacitor discharges through a load with RC = 0.20 s. Calculate the time for its p.d. to fall to 95 % of its peak, in ms.', NULL, 2, 'numeric'::answer_type, '10.26 ms', 'ms', false, NULL, false, NULL, 't = RC ln(1/0.95) = 0.20 × ln 1.0526 = 0.0103 s. In ms: 0.01026 × 1000 = 10.3. Mark scheme (3 marks). C1: logs. C1: conversion. A1: t = 10.3 ms.', 3),
('2ecf307a-6ab8-5b23-872b-163917903456', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '71ba01f7-9a9e-5018-974d-21999c276ce5', 'a-level', '27.4', '9702 coursebook 27.4 · Rectification and smoothing', 39, 39, 'Why does the smoothing capacitor''s p.d. rise only during a short part of each cycle?', NULL, 2, 'multiple_choice'::answer_type, 'The diodes conduct only when the rectified input is higher than the capacitor''s p.d.', NULL, false, NULL, false, NULL, 'Most of the time the diodes are reverse-biased. Mark scheme (3 marks). C1: diode forward-biased only near peaks. C1: capacitor discharges otherwise. A1: C (The diodes conduct only when the rectified input is higher than the capacitor''s p.d.).', 3),
('5bfee1b3-44c9-5ee4-bcf2-0b858feb14fd', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '71ba01f7-9a9e-5018-974d-21999c276ce5', 'a-level', '27.4', '9702 coursebook 27.4 · Rectification and smoothing', 40, 40, 'A smoothed output rises to a peak of 15.0 V and falls to 14.4 V before the next peak. Estimate the mean output voltage.', NULL, 2, 'numeric'::answer_type, '14.7', 'V', false, NULL, false, NULL, 'For a small ripple the voltage varies almost linearly, so mean ≈ (15.0 + 14.4) ÷ 2 = 14.7 V. Mark scheme (4 marks). M1: average of peak and trough. C1: substitution. C1: value. A1: V = 14.7 V.', 4),
('f888503b-e26a-5290-aa13-fa0771815b1c', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '71ba01f7-9a9e-5018-974d-21999c276ce5', 'a-level', '27.4', '9702 coursebook 27.4 · Rectification and smoothing', 41, 41, 'Which describes the smoothed output of a half-wave rectifier?', NULL, 2, 'multiple_choice'::answer_type, 'A sharp rise near each positive peak, followed by a slow fall for the rest of the cycle', NULL, false, NULL, false, NULL, 'The capacitor charges near the peak and then discharges through the load. Mark scheme (3 marks). C1: charge near peak. C1: slow exponential discharge. A1: A (A sharp rise near each positive peak, followed by a slow fall for the rest of the cycle).', 3),
('1168aa5c-a1fa-599c-add6-b06015a223e7', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '71ba01f7-9a9e-5018-974d-21999c276ce5', 'a-level', '27.4', '9702 coursebook 27.4 · Rectification and smoothing', 42, 42, 'A transformer gives 12 V r.m.s. to a bridge rectifier; two diodes, each dropping 0.70 V, conduct at a time. The output is smoothed by a 2200 µF capacitor and feeds a 100 Ω load. The supply is 50 Hz. (a) Calculate the peak output voltage. (b) Calculate the time constant. (c) Estimate the ripple using ΔV ≈ V₀t/RC. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '0.7078', 'V', false, NULL, false, NULL, '(a) V₀ = √2 × 12 − 1.4 = 15.6 V. (b) RC = 100 × 2200 × 10⁻⁶ = 0.22 s. (c) t = 0.010 s, so ΔV ≈ 15.57 × 0.010 ÷ 0.22 = 0.708 V. Mark scheme (6 marks). C1: V₀ with diode drops. C1: RC. C1: t for full-wave. M1: ΔV ≈ V₀t/RC. C1: value. A1: ΔV = 0.708 V.', 6),
('63a29847-85d6-5544-bd5a-079aeb12f9e3', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '71ba01f7-9a9e-5018-974d-21999c276ce5', 'a-level', '27.4', '9702 coursebook 27.4 · Rectification and smoothing', 43, 43, 'A half-wave rectifier on a 50 Hz supply has a smoothing capacitor charged to 10 V at each peak, with RC = 0.10 s. (a) State the time between peaks. (b) Calculate the p.d. just before the next peak. (c) Calculate the ripple. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '1.813', 'V', false, NULL, false, NULL, '(a) 0.020 s. (b) V = 10 × e^(−0.020/0.10) = 8.19 V. (c) Ripple = 10 − 8.187 = 1.81 V. Mark scheme (5 marks). C1: one peak per cycle. C1: V = V₀e^(−t/RC). C1: ripple. B1: approximation ΔV ≈ V₀t/RC gives 2.0 V. A1: ΔV = 1.81 V.', 5),
('49034181-bb96-5a9b-8682-c334e82e14ea', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '71ba01f7-9a9e-5018-974d-21999c276ce5', 'a-level', '27.4', '9702 coursebook 27.4 · Rectification and smoothing', 44, 44, 'A power supply delivers 50 mA to a load from a full-wave rectifier on a 50 Hz supply. The ripple must be no more than 0.20 V. (a) Calculate the charge supplied to the load between peaks. (b) Calculate the smoothing capacitance needed, in µF. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '2500', 'µF', false, NULL, false, ARRAY['0.0025']::text[], '(a) ΔQ = It = 0.050 × 0.010 = 5.0 × 10⁻⁴ C. (b) C = ΔQ/ΔV = 5.0 × 10⁻⁴ ÷ 0.20 = 2.5 × 10⁻³ F. In µF: 2.5 × 10⁻³ × 10⁶ = 2500. Mark scheme (6 marks). C1: t = 0.010 s. C1: ΔQ = It. M1: C = ΔQ/ΔV. C1: value. C1: conversion. A1: C = 2500 µF.', 6),
('46b89f11-b8da-5300-be23-9ae43dd64d38', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '71ba01f7-9a9e-5018-974d-21999c276ce5', 'a-level', '27.4', '9702 coursebook 27.4 · Rectification and smoothing', 45, 45, 'A full-wave rectifier on a 50 Hz supply feeds 0.12 A to a load through a 1000 µF smoothing capacitor. (a) Calculate the charge delivered between peaks. (b) Calculate the ripple. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '1.2', 'V', false, NULL, false, NULL, '(a) ΔQ = 0.12 × 0.010 = 1.2 × 10⁻³ C. (b) ΔV = ΔQ/C = 1.2 × 10⁻³ ÷ 1000 × 10⁻⁶ = 1.2 V. Mark scheme (5 marks). C1: t between peaks. C1: ΔQ. M1: ΔV = ΔQ/C. C1: value. A1: ΔV = 1.2 V.', 5),
('1b74c3a2-646e-535f-aca2-4521767e06ff', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '71ba01f7-9a9e-5018-974d-21999c276ce5', 'a-level', '27.4', '9702 coursebook 27.4 · Rectification and smoothing', 46, 46, 'A smoothed full-wave output on a 50 Hz supply rises to 14.0 V and falls to 13.2 V before each new peak. The load is 470 Ω. (a) State the ripple. (b) Estimate the mean load current. (c) Estimate the smoothing capacitance, in µF. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '361.7', 'µF', false, NULL, false, ARRAY['3.617e-4']::text[], '(a) 14.0 − 13.2 = 0.80 V. (b) I ≈ 13.6 ÷ 470 = 0.0289 A. (c) C ≈ It/ΔV = 0.02894 × 0.010 ÷ 0.80 = 3.62 × 10⁻⁴ F. In µF: 3.617 × 10⁻⁴ × 10⁶ = 362. Mark scheme (6 marks). C1: ripple. C1: mean voltage. C1: I = V/R. M1: C = It/ΔV. C1: value. A1: C = 362 µF.', 6),
('a42b7458-931c-5850-a57f-8cc1535bc554', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '71ba01f7-9a9e-5018-974d-21999c276ce5', 'a-level', '27.4', '9702 coursebook 27.4 · Rectification and smoothing', 47, 47, 'A smoothed full-wave rectifier gives a ripple of 0.30 V. (a) Explain why the ripple would roughly double with half-wave rectification and the same capacitor and load. (b) State the expected ripple with half-wave rectification. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '0.6', 'V', false, NULL, false, NULL, '(a) With half-wave rectification the capacitor discharges for a whole period (20 ms) instead of half a period (10 ms) between peaks. (b) ΔV ≈ 2 × 0.30 = 0.60 V. Mark scheme (5 marks). B1: discharge time doubled. M1: ΔV ∝ t. C1: factor 2. C1: value. A1: ΔV = 0.60 V.', 5),
('3093b260-6771-5103-a316-9c611697de11', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '71ba01f7-9a9e-5018-974d-21999c276ce5', 'a-level', '27.4', '9702 coursebook 27.4 · Rectification and smoothing', 48, 48, 'A smoothed supply gives a nearly steady 15 V across a 100 Ω load. (a) Calculate the load current. (b) Calculate the power delivered to the load. (c) The transformer supplies 2.6 W. Calculate the efficiency of the rectifier and smoothing circuit. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '2.25', 'W', false, NULL, false, NULL, '(a) I = 15 ÷ 100 = 0.15 A. (b) P = 15² ÷ 100 = 2.25 W. (c) Efficiency = 2.25 ÷ 2.6 × 100 = 86.5 %, the rest being lost mostly in the diodes. Mark scheme (5 marks). C1: I = V/R. C1: P = V²/R. C1: efficiency. B1: losses in diodes. A1: P = 2.25 W.', 5),
('8935b6ff-5664-5141-b3fa-272b5cf53ad2', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '71ba01f7-9a9e-5018-974d-21999c276ce5', 'a-level', '27.4', '9702 coursebook 27.4 · Rectification and smoothing', 49, 49, 'A bridge rectifier is fed with 6.0 V r.m.s. Each diode has a forward p.d. of 0.70 V. (a) Explain why two diode drops must be subtracted. (b) Calculate the peak output voltage. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '7.085', 'V', false, NULL, false, NULL, '(a) In each half cycle, the current passes through two diodes in series with the load. (b) V₀ = √2 × 6.0 − 2 × 0.70 = 7.09 V. Mark scheme (5 marks). B1: two diodes in each path. C1: √2 × 6.0. C1: subtract 1.4 V. C1: value. A1: V₀ = 7.09 V.', 5),
('491027ae-a457-551d-b9a8-4488bdae6020', '94fd6e1e-0c0d-4097-b9f4-51457e7b9b07', '71ba01f7-9a9e-5018-974d-21999c276ce5', 'a-level', '27.4', '9702 coursebook 27.4 · Rectification and smoothing', 50, 50, 'A smoothed full-wave rectifier on a 50 Hz supply has a ripple of 0.50 V. The same circuit is then used on a 60 Hz supply. (a) Explain why the ripple changes. (b) Calculate the new ripple, using ΔV ∝ time between peaks. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '0.4167', 'V', false, NULL, false, NULL, '(a) At 60 Hz the peaks come more often, so the capacitor discharges for less time. (b) ΔV = 0.50 × 50 ÷ 60 = 0.417 V. Mark scheme (5 marks). B1: shorter gap between peaks. M1: ΔV ∝ 1/f. C1: substitution. C1: value. A1: ΔV = 0.417 V.', 5)
